private func hierarchyRow(_ label: String, nodeID: String) -> some View {
    let children = store.childNodes(of: nodeID).map(\.id).joined(separator: ", ")
    let edges = store.childEdges(of: nodeID).map(\.id).joined(separator: ", ")
    let descendants = store.descendantNodeIDs(of: nodeID).count

    return VStack(alignment: .leading, spacing: 2) {
        HStack {
            Text(label)
                .foregroundStyle(.secondary)
            Spacer(minLength: 8)
            Text("\(descendants)")
        }
        Text("nodes: \(children.isEmpty ? "-" : children)")
            .lineLimit(2)
        Text("edges: \(edges.isEmpty ? "-" : edges)")
            .lineLimit(1)
    }
}

private func topLevelNodeIDs(from nodeIDs: Set<String>) -> Set<String> {
    nodeIDs.filter { nodeID in
        var currentParentID = nodeLookup[nodeID]?.parentID
        while let parentID = currentParentID {
            if nodeIDs.contains(parentID) { return false }
            currentParentID = nodeLookup[parentID]?.parentID
        }
        return true
    }
}

static func backEdgeIndices(ids: [String], edges: [(String, String)]) -> Set<Int> {
    var adjacency: [String: [Int]] = [:]
    for (index, edge) in edges.enumerated() { adjacency[edge.0, default: []].append(index) }
    var color: [String: Int] = [:]   // 0 = white, 1 = grey (on stack), 2 = black
    var back = Set<Int>()
    func visit(_ id: String) {
        color[id] = 1
        for index in adjacency[id] ?? [] {
            let target = edges[index].1
            switch color[target] ?? 0 {
            case 1: back.insert(index)          // edge into an ancestor → back edge
            case 0: visit(target)
            default: break
            }
        }
        color[id] = 2
    }
    for id in ids where (color[id] ?? 0) == 0 { visit(id) }
    return back
}

static func layeredRoutes(
    ids: [String],
    sizes: [String: CGSize],
    layeringEdges: [(String, String)],
    routingEdges: [(from: String, to: String)],
    layerGap: CGFloat,
    nodeGap: CGFloat,
    margin: CGFloat,
    edgeLabelSizes: [CGSize?]? = nil
) -> (frames: [String: CGRect], size: CGSize, routes: [[CGPoint]], labelAnchors: [CGPoint?]) {
    let layerBack = backEdgeIndices(ids: ids, edges: layeringEdges)
    let forward = layeringEdges.enumerated().filter { !layerBack.contains($0.offset) }.map(\.element)
    let layerOf = assignLayers(ids: ids, edges: forward)
    let layerCount = (layerOf.values.max() ?? 0) + 1

    // Dummy nodes for every routing edge spanning more than one layer.
    var layers: [[String]] = Array(repeating: [], count: layerCount)
    for id in ids where layerOf[id] != nil { layers[layerOf[id]!].append(id) }
    var allSizes = sizes
    var chains: [[String]] = []
    var segmentEdges: [(String, String)] = []
    var dummies: Set<String> = []
    // Labeled edges between ADJACENT layers carry their text in the
    // inter-layer gap; grow each gap to fit the tallest such label so the
    // chip never crowds the boxes above or below it.
    var gapExtra = [CGFloat](repeating: 0, count: max(layerCount, 1))
    if let edgeLabelSizes {
        for (index, edge) in routingEdges.enumerated() {
            guard let labelSize = edgeLabelSizes[index],
                  let lu = layerOf[edge.from], let lv = layerOf[edge.to],
                  abs(lu - lv) == 1 else { continue }
            let gap = min(lu, lv)
            gapExtra[gap] = max(gapExtra[gap], labelSize.height + 6)
        }
    }
    for (index, edge) in routingEdges.enumerated() {
        guard let lu = layerOf[edge.from], let lv = layerOf[edge.to] else { chains.append([]); continue }
        let lo = min(lu, lv), hi = max(lu, lv)
        if hi - lo <= 1 {
            chains.append([edge.from, edge.to])
            segmentEdges.append((edge.from, edge.to))
            continue
        }
        var midByLayer: [(layer: Int, id: String)] = []
        // ELK-style label reservation: the MEDIAN dummy of a labeled edge
        // is widened to the label's size, so ordering and Brandes-Köpf
        // reserve real horizontal space for the text instead of the label
        // being squeezed in afterwards. `placeRunLabels` (below) then anchors
        // the caption on the resulting straight channel.
        let labelSize = edgeLabelSizes?[index] ?? nil
        let medianLayer = (lo + 1 + hi - 1) / 2
        for layer in (lo + 1)...(hi - 1) {
            let dummy = "\u{a7}b\(index).\(layer)"
            layers[layer].append(dummy)
            if let labelSize, layer == medianLayer {
                allSizes[dummy] = CGSize(width: max(16, labelSize.width + 8), height: 1)
            } else {
                allSizes[dummy] = CGSize(width: 16, height: 1)
            }
            dummies.insert(dummy)
            midByLayer.append((layer, dummy))
        }
        let mids = (lu < lv ? midByLayer : midByLayer.reversed()).map(\.id)
        let chain = [edge.from] + mids + [edge.to]
        chains.append(chain)
        for k in 0..<(chain.count - 1) { segmentEdges.append((chain[k], chain[k + 1])) }
    }

    // Order, then assign x with Brandes–Köpf (top-down; cross axis is x) so
    // dummy channels and box columns align into straight runs.
    let ordered = barycenterOrder(layers: layers, edges: segmentEdges)
    var breadth: [String: CGFloat] = [:]
    for layer in ordered { for id in layer { breadth[id] = allSizes[id]?.width ?? 0 } }
    var xCenter = brandesKoepfX(
        layers: ordered, segments: segmentEdges, breadth: breadth,
        dummies: dummies, minGap: nodeGap)
    // Same near-alignment jog fix as the flowchart pipeline: BK's
    // balancing leaves single-parent chains a few points off centre.
    straightenChains(layers: ordered, segments: segmentEdges,
                     breadth: breadth, minGap: nodeGap, center: &xCenter)
    var minCross = CGFloat.greatestFiniteMagnitude
    var maxCross = -CGFloat.greatestFiniteMagnitude
    for layer in ordered {
        for id in layer {
            let w = allSizes[id]?.width ?? 0
            let c = xCenter[id] ?? 0
            minCross = min(minCross, c - w / 2)
            maxCross = max(maxCross, c + w / 2)
        }
    }
    let shiftX = margin - (minCross.isFinite ? minCross : 0)
    let crossExtent = maxCross > minCross ? maxCross - minCross : 0

    var frames: [String: CGRect] = [:]
    var y = margin
    for (layerIndex, layer) in ordered.enumerated() {
        let layerHeight = layer.map { allSizes[$0]?.height ?? 0 }.max() ?? 0
        for id in layer {
            let size = allSizes[id] ?? .zero
            let cx = (xCenter[id] ?? 0) + shiftX
            frames[id] = CGRect(x: cx - size.width / 2, y: y, width: size.width, height: size.height)
        }
        y += layerHeight + layerGap
        if layerIndex < gapExtra.count { y += gapExtra[layerIndex] }
    }

    // Antiparallel detection: an edge whose reverse also exists must not
    // share the reverse's column, or the two render as one line.
    var directedPairs = Set<String>()
    for edge in routingEdges { directedPairs.insert(edge.from + "\u{1}" + edge.to) }

    // Route each edge through its chain waypoints.
    var routes: [[CGPoint]] = []
    for (ci, chain) in chains.enumerated() {
        guard chain.count >= 2, let fromFrame = frames[chain[0]], let toFrame = frames[chain[chain.count - 1]] else {
            routes.append([.zero, .zero]); continue
        }
        // Self-loop (an edge from a box back to itself, e.g. an ER
        // "subcategory of" parent_id): route it as a small loop off the
        // right side, never a straight line through the box interior. The
        // top/bottom bars stay short (a wider loop would gore a neighbour);
        // the caption rides the vertical return run, which we grow to the
        // label height plus a stub on each side so a word like "retry" isn't
        // crammed onto the default span (`label-crowds-edge`).
        if chain[0] == chain[chain.count - 1] {
            let f = fromFrame
            let ext: CGFloat = 24
            let labelH = (edgeLabelSizes?[ci] ?? nil)?.height ?? 0
            let vHalf = max(min(f.height * 0.24, 13), labelH / 2 + edgeLabelStub)
            let yHi = f.midY - vHalf
            let yLo = f.midY + vHalf
            routes.append([
                CGPoint(x: f.maxX, y: yHi),
                CGPoint(x: f.maxX + ext, y: yHi),
                CGPoint(x: f.maxX + ext, y: yLo),
                CGPoint(x: f.maxX, y: yLo),
            ])
            continue
        }
        // Same layer → route the short way through side faces, UNLESS the
        // direct line would cross another box sitting between the two: then
        // dip into the gap just below the row and cross there instead of
        // straight through the intervening box.
        if abs(fromFrame.midY - toFrame.midY) < 1 {
            let right = toFrame.midX >= fromFrame.midX
            let start = CGPoint(x: right ? fromFrame.maxX : fromFrame.minX, y: fromFrame.midY)
            let end = CGPoint(x: right ? toFrame.minX : toFrame.maxX, y: toFrame.midY)
            let lo = min(start.x, end.x), hi = max(start.x, end.x)
            let blocked = frames.contains { id, fr in
                id != chain[0] && id != chain[chain.count - 1] && !dummies.contains(id)
                    && abs(fr.midY - fromFrame.midY) < 1
                    && fr.minX < hi - 2 && fr.maxX > lo + 2
            }
            if blocked {
                let dy = fromFrame.maxY + 16
                routes.append([start, CGPoint(x: start.x, y: dy), CGPoint(x: end.x, y: dy), end])
            } else {
                routes.append([start, end])
            }
            continue
        }
        let dummyCenters = chain[1..<(chain.count - 1)].compactMap { frames[$0].map { CGPoint(x: $0.midX, y: $0.midY) } }
        // Straight column: when the two boxes' x-ranges overlap and there
        // are no dummies to route around, attach both ends at one shared x
        // so the edge is a single straight segment — no tiny S-hook from a
        // near-alignment offset.
        let overlapLo = max(fromFrame.minX, toFrame.minX) + 4
        let overlapHi = min(fromFrame.maxX, toFrame.maxX) - 4
        if dummyCenters.isEmpty, overlapLo <= overlapHi {
            var x = min(max((fromFrame.midX + toFrame.midX) / 2, overlapLo), overlapHi)
            let down = toFrame.midY >= fromFrame.midY
            // If a reverse edge exists between the same pair, place the two
            // as a centred block a full separation apart (not an independent
            // ±offset, which the overlap clamp then compresses), so they read
            // as two clear parallel lines (e.g. state "connect"/"fail").
            if directedPairs.contains(chain[chain.count - 1] + "\u{1}" + chain[0]) {
                let half = min(boxAntiparallelSep / 2, (overlapHi - overlapLo) / 2)
                let center = min(max(x, overlapLo + half), overlapHi - half)
                x = center + (down ? half : -half)
            }
            let start = CGPoint(x: x, y: down ? fromFrame.maxY : fromFrame.minY)
            let end = CGPoint(x: x, y: down ? toFrame.minY : toFrame.maxY)
            routes.append([start, end])
            continue
        }
        let firstNext = dummyCenters.first ?? CGPoint(x: toFrame.midX, y: toFrame.midY)
        let lastPrev = dummyCenters.last ?? CGPoint(x: fromFrame.midX, y: fromFrame.midY)
        func attach(_ f: CGRect, towardX: CGFloat, bottom: Bool) -> CGPoint {
            CGPoint(x: min(max(towardX, f.minX + 4), f.maxX - 4), y: bottom ? f.maxY : f.minY)
        }
        let start = attach(fromFrame, towardX: firstNext.x, bottom: firstNext.y >= fromFrame.midY)
        let end = attach(toFrame, towardX: lastPrev.x, bottom: lastPrev.y > toFrame.midY)
        let points = routePolyline([start] + dummyCenters + [end], horizontal: false)
        routes.append(points)
    }

    // Push horizontal runs out of box bands. A cross-layer edge's jog is
    // placed at the midpoint between its dummy and the target, which for a
    // TALL intermediate box lands inside it (class "contains" jogging at
    // y=272 through Customer, whose band is y179–300). Move any interior
    // horizontal segment that crosses a box to the nearest clear y — the
    // connecting vertical legs sit in dummy channels, so lengthening them
    // stays clear. Routes with no crossing are untouched.
    let realFrames = ids.compactMap { dummies.contains($0) ? nil : frames[$0] }
    for ri in routes.indices {
        var pts = routes[ri]
        guard pts.count >= 4 else { continue }
        var i = 1
        while i < pts.count - 2 {
            let a = pts[i], b = pts[i + 1]
            if abs(a.y - b.y) < 0.5 && abs(a.x - b.x) > 1 {
                let lo = min(a.x, b.x) + 2, hi = max(a.x, b.x) - 2
                let pad: CGFloat = 16
                func crosses(_ yy: CGFloat) -> Bool {
                    realFrames.contains { $0.minY + 2 < yy && $0.maxY - 2 > yy && $0.minX < hi && $0.maxX > lo }
                }
                // A destination y must clear every crossed box by `pad`, so the
                // run sits well inside the gap rather than skimming a border.
                func clearWithPadding(_ yy: CGFloat) -> Bool {
                    !realFrames.contains { $0.minY - pad < yy && $0.maxY + pad > yy && $0.minX < hi && $0.maxX > lo }
                }
                if crosses(a.y) {
                    var moved: CGFloat?
                    var d: CGFloat = 4
                    while d <= 300 {
                        for cand in [a.y + d, a.y - d] where clearWithPadding(cand) { moved = cand; break }
                        if moved != nil { break }
                        d += 4
                    }
                    if let ny = moved { pts[i].y = ny; pts[i + 1].y = ny }
                }
            }
            i += 1
        }
        routes[ri] = pts
    }

    // Same guarantee the flowchart router gives: no two edges' runs may
    // coincide on one track. Catches long/back-edge channels that land on a
    // box column (the antiparallel block above only covers adjacent pairs).
    separateRuns(&routes, horizontal: false, minSep: boxAntiparallelSep)

    var routeMaxX = crossExtent + margin
    for pts in routes { for p in pts { routeMaxX = max(routeMaxX, p.x) } }
    var size = CGSize(width: max(crossExtent, routeMaxX - margin) + margin * 2, height: y - layerGap + margin)
    // Place every caption on the longest clean straight run of its final
    // route, collision-avoiding node boxes, other captions, bends, and
    // crossings — the same run-based placement the flowchart pipeline uses,
    // so a state/class/ER label never lands on a corner or a junction, and
    // sibling adjacent-layer labels that share an inter-layer gap slide
    // apart instead of stacking on one midpoint. (The reserved median-dummy
    // channel and the grown gap give this pass the room it needs.)
    let realFrameList = ids.compactMap { dummies.contains($0) ? nil : frames[$0] }
    let labelSizes: [CGSize?] = routingEdges.indices.map { edgeLabelSizes?[$0] ?? nil }
    let labelAnchors = placeRunLabels(routes: routes, labelSizes: labelSizes,
                                      nodeFrames: realFrameList)
    // Grow the canvas for any caption nudged past the content box — the same
    // post-placement expansion layoutFlat performs — so a label on the
    // rightmost/bottom-most run (or a perpendicular nudge off it) is never
    // clipped or flagged off-canvas.
    for (i, anchor) in labelAnchors.enumerated() {
        guard let lp = anchor, let sz = labelSizes[i] else { continue }
        size.width = max(size.width, lp.x + sz.width / 2 + margin)
        size.height = max(size.height, lp.y + sz.height / 2 + margin)
    }
    // Dummy frames are internal scaffolding — don't leak them.
    for dummy in dummies { frames[dummy] = nil }
    return (frames, size, routes, labelAnchors)
}

public static func layout(_ diagram: ClassDiagram, measure: DiagramTextMeasurer,
                          spacing: DiagramSpacing = .regular) -> ClassLayout {
    DiagramTextScale.run(spacing, measure) { measure in
        scaledLayout(diagram, measure: measure, spacing: spacing)
    }
}

public static func layout(_ diagram: C4Diagram, measure: DiagramTextMeasurer) -> C4Layout {
    // Long labels cost height (#70). The canvas caps at 3999pt, so if the
    // whole chart wouldn't fit at the generous line caps, lay it out again
    // at tighter ones, down to 2 title / 3 detail lines — every cut still
    // ends in "…" — rather than let the canvas clip whole rows. The last
    // caps are the ones the layout always had (technology included), so
    // the result is never taller than it was before #70.
    let caps: [(title: Int, detail: Int)] = [(4, 12), (3, 6), (2, 3)]
    for cap in caps {
        let (layout, height) = layout(diagram, measure: measure, titleCap: cap.title, detailCap: cap.detail)
        if height <= 3999 || cap == caps.last! { return layout }
    }
    preconditionFailure("unreachable: the last cap always returns")
}

public static func layout(_ chart: Flowchart, measure: DiagramTextMeasurer,
                          spacing: DiagramSpacing = .regular) -> FlowchartLayout {
    DiagramTextScale.run(spacing, measure) { measure in
        scaledLayout(chart, measure: measure, spacing: spacing)
    }
}

static func placeRunLabels(
    routes: [[CGPoint]],
    labelSizes: [CGSize?],
    nodeFrames: [CGRect],
    headInsets: [CGFloat] = [],
    tailInsets: [CGFloat] = [],
    labelRuns: [Int?] = []
) -> [CGPoint?] {
    // Nothing to place: no obstacle needs reading.
    guard routes.indices.contains(where: { $0 < labelSizes.count && labelSizes[$0] != nil && routes[$0].count >= 2 }) else {
        return [CGPoint?](repeating: nil, count: routes.count)
    }
    let obstacles = nodeFrames.map { $0.insetBy(dx: -3, dy: -3) }
    // Fixtures every caption must avoid: the interior bends of every route
    // (a corner) and the points where two routes cross (a junction).
    var bends: [CGPoint] = []
    for pts in routes where pts.count > 2 { bends.append(contentsOf: pts[1..<(pts.count - 1)]) }
    let crossings = routeCrossingPoints(routes)
    // Every term of a candidate's score is zero for an obstacle that isn't
    // near it, and adding zero leaves a sum exactly as it was, so each
    // candidate reads only what a grid finds near it, in the same order as
    // before: the placement is bit for bit the all-pairs one, in near-linear
    // time.
    let obstacleGrid = PlacementGrid(obstacles)
    let bendGrid = PlacementGrid(points: bends)
    let crossingGrid = PlacementGrid(points: crossings)
    // Arrowhead tips: the head end of every route (last point). Treated as a
    // small obstacle REGION, not just a point, so a label keeps clear of the
    // arrowhead rather than hugging it. A route's own tips are excluded when
    // scoring it — its own stub already reserves space at the run ends.
    let arrowTips: [(route: Int, p: CGPoint)] = routes.indices.compactMap {
        routes[$0].count >= 2 ? ($0, routes[$0].last!) : nil
    }
    let tipGrid = PlacementGrid(arrowTips.map { CGRect(origin: $0.p, size: .zero) })
    let gap = flowchartLabelGap

    // Distance from a point to the nearest edge of a rect (0 inside/on it).
    func pointRectDistance(_ p: CGPoint, _ r: CGRect) -> CGFloat {
        let dx = max(r.minX - p.x, 0, p.x - r.maxX)
        let dy = max(r.minY - p.y, 0, p.y - r.maxY)
        return hypot(dx, dy)
    }

    var anchors = [CGPoint?](repeating: nil, count: routes.count)
    var labelRects: [CGRect] = []
    var labelGrid = PlacementGrid([])
    func placeLabel(_ rect: CGRect) {
        labelGrid.insert(labelRects.count, rect)
        labelRects.append(rect)
    }

    for i in routes.indices {
        guard let sz = labelSizes[i], routes[i].count >= 2 else { continue }
        let pts = routes[i]
        let w = sz.width + 6, h = sz.height + 2
        let hIn = i < headInsets.count ? headInsets[i] : 0
        let tIn = i < tailInsets.count ? tailInsets[i] : 0

        // Straight runs of this route (segments; the polyline is already
        // collinear-simplified, so each segment is a maximal run). lo/hi are
        // the ARROW-FREE bounds: the terminal runs are shrunk by the head /
        // tail arrowhead so the caption centers on the arrow-free stretch.
        struct Run { let horizontal: Bool; let lo: CGFloat; let hi: CGFloat; let fixed: CGFloat; let index: Int }
        var runs: [Run] = []
        let onlyRun = i < labelRuns.count ? labelRuns[i] : nil
        for k in 0..<(pts.count - 1) where onlyRun == nil || onlyRun == k {
            let a = pts[k], b = pts[k + 1]
            let dx = abs(a.x - b.x), dy = abs(a.y - b.y)
            guard max(dx, dy) > 0.5 else { continue }
            let horiz = dx >= dy
            var lo = horiz ? min(a.x, b.x) : min(a.y, b.y)
            var hi = horiz ? max(a.x, b.x) : max(a.y, b.y)
            func alongCoord(_ p: CGPoint) -> CGFloat { horiz ? p.x : p.y }
            if k == 0, tIn > 0 {                       // this run touches the tail
                if abs(alongCoord(a) - lo) < 0.5 { lo += tIn } else { hi -= tIn }
            }
            if k == pts.count - 2, hIn > 0 {           // this run touches the head
                if abs(alongCoord(b) - hi) < 0.5 { hi -= hIn } else { lo += hIn }
            }
            if hi < lo { let m = (lo + hi) / 2; lo = m; hi = m }   // fully eaten: hairline
            runs.append(Run(
                horizontal: horiz, lo: lo, hi: hi,
                fixed: horiz ? a.y : a.x, index: k))
        }
        guard !runs.isEmpty else {
            let a = pts[0], b = pts[pts.count - 1]
            let p = CGPoint(x: (a.x + b.x) / 2, y: (a.y + b.y) / 2)
            placeLabel(CGRect(x: p.x - w / 2, y: p.y - h / 2, width: w, height: h))
            anchors[i] = p; continue
        }
        // Longest run first; segment index breaks ties (deterministic).
        let ranked = runs.enumerated().sorted {
            let la = $0.element.hi - $0.element.lo, lb = $1.element.hi - $1.element.lo
            return la != lb ? la > lb : $0.element.index < $1.element.index
        }.map(\.element)

        var best = CGPoint(x: 0, y: 0)
        var bestScore = CGFloat.greatestFiniteMagnitude
        var haveBest = false
        for (rank, run) in ranked.enumerated() {
            let along = run.horizontal ? w : h        // caption extent along the run
            let perp = run.horizontal ? h : w         // caption extent across the run
            let mid = (run.lo + run.hi) / 2
            // Slide range along the run that keeps a full stub on each side;
            // a fine sweep so the label can settle JUST clear of an obstacle
            // instead of jumping to the far end. da = 0 is always the
            // midpoint (the default), and the |da| penalty keeps it there
            // unless a clearance forces a move.
            let slack = max(0, (run.hi - run.lo) / 2 - along / 2 - edgeLabelStub)
            var alongShifts: [CGFloat] = [0]
            if slack > 1 {
                let steps = 12
                for s in 1...steps {
                    let v = slack * CGFloat(s) / CGFloat(steps)
                    alongShifts.append(v); alongShifts.append(-v)
                }
                // Comfort-stagger candidates: the MINIMAL slide along this run
                // that clears the comfort gap just past an already-placed
                // caption (measuring on the run's OWN axis). The uniform sweep
                // above is coarse — its first step can overshoot into a
                // neighbouring node's clearance and lose to the crowded
                // midpoint — so we add the exact offset that opens a comfort
                // gap and nothing more. The DOWN/RIGHT slide is offered first
                // so the later, further-along caption is the one that yields.
                for l in labelRects {
                    let lLo = run.horizontal ? l.minX : l.minY
                    let lHi = run.horizontal ? l.maxX : l.maxY
                    let down = (lHi + gap + along / 2 + 0.5) - mid
                    let up   = (lLo - gap - along / 2 - 0.5) - mid
                    for s in [down, up] where abs(s) <= slack { alongShifts.append(s) }
                }
            }
            // A shift offered twice scores the same twice, and only a
            // strictly lower score wins, so a repeat can't change the pick.
            var offered: Set<CGFloat> = []
            alongShifts = alongShifts.filter { offered.insert($0).inserted }
            let perpNudges: [CGFloat] = [0, perp / 2 + gap / 2, -(perp / 2 + gap / 2)]
            for da in alongShifts {
                for dp in perpNudges {
                    let cAlong = mid + da
                    let cx = run.horizontal ? cAlong : run.fixed + dp
                    let cy = run.horizontal ? run.fixed + dp : cAlong
                    let rect = CGRect(x: cx - w / 2, y: cy - h / 2, width: w, height: h)
                    // The score's tail: what this candidate pays however
                    // clear it is. Every term before it is at least 0, and
                    // adding the same terms in the same order is monotone,
                    // so the tail summed from 0 bounds the score from
                    // below. A candidate whose bound already reaches the
                    // best can't win (only a strictly lower score does),
                    // so it isn't scored: the pick is the same.
                    let stub = min((cAlong - along / 2) - run.lo, run.hi - (cAlong + along / 2))
                    let offMargin = rect.minX < flowchartMargin || rect.minY < flowchartMargin
                    func tail(_ score: CGFloat) -> CGFloat {
                        var score = score
                        if stub < edgeLabelStub { score += (edgeLabelStub - stub) * 6 }
                        score += abs(da) * 1.4           // stay at the MIDPOINT
                        score += abs(dp) * 1.5           // prefer sitting ON the line
                        score += CGFloat(rank) * 2       // prefer the longer run
                        if offMargin { score += 1_000 }
                        return score
                    }
                    if haveBest, tail(0) >= bestScore { continue }
                    var score: CGFloat = 0
                    for k in obstacleGrid.near(rect) { score += overlapArea(rect, obstacles[k]) * 4 }
                    // A caption adds nothing past `gap` on either axis.
                    for k in labelGrid.near(rect.insetBy(dx: -gap, dy: -gap)) {
                        let l = labelRects[k]
                        score += overlapArea(rect, l) * 3
                        // Comfort gap: two captions that don't overlap but sit
                        // within `gap` of each other on BOTH axes still read as
                        // crowded (e.g. `fail`/`reject` on parallel vertical
                        // back-edge channels — routing-fixed x's, similar y's).
                        // `sep` is the clearance on the better-separated axis; a
                        // shortfall is penalized so the label slides ALONG its
                        // own run to open the gap. Sliding along the run is the
                        // cheapest move, so the stagger lands on the crowding
                        // axis: parallel vertical runs stagger vertically (the
                        // sweep tries the DOWN shift first, so the later/rightmost
                        // caption is pushed down), parallel horizontal runs
                        // stagger horizontally. Only bites when the gap is
                        // violated; otherwise it is 0 and the label stays put.
                        let dxGap = max(l.minX - rect.maxX, rect.minX - l.maxX, 0)
                        let dyGap = max(l.minY - rect.maxY, rect.minY - l.maxY, 0)
                        let sep = max(dxGap, dyGap)
                        if sep < gap { score += (gap - sep) * 8 }
                    }
                    let probe = rect.insetBy(dx: -1, dy: -1)
                    // Each adds the same 120, so only how many lie in the probe
                    // matters (added one at a time, as before).
                    for _ in 0..<bendGrid.count(in: probe, where: { probe.contains(bends[$0]) }) { score += 120 }
                    for _ in 0..<crossingGrid.count(in: probe, where: { probe.contains(crossings[$0]) }) { score += 120 }
                    // Arrowhead clearance: a foreign arrowhead tip within the
                    // comfortable gap of the caption frame is an obstacle.
                    // Every foreign tip counts (only this route's own head is
                    // exempt, via `tip.route != i`). A foreign arrowhead that
                    // happens to coincide with this route's own endpoint used
                    // to be skipped, but the linter's `label-on-fixture` rule
                    // does NOT exempt it — so skipping it here let the placer
                    // pick an anchor that then failed lint. Score all of them.
                    for k in tipGrid.near(rect.insetBy(dx: -gap, dy: -gap)) where arrowTips[k].route != i {
                        let tip = arrowTips[k]
                        let d = pointRectDistance(tip.p, rect)
                        if d < gap { score += (gap - d) * 6 }
                    }
                    // Stub on each side of the caption on this run, then
                    // the rest of the tail.
                    score = tail(score)
                    if !haveBest || score < bestScore {
                        bestScore = score; best = CGPoint(x: cx, y: cy); haveBest = true
                    }
                }
            }
        }
        placeLabel(CGRect(x: best.x - w / 2, y: best.y - h / 2, width: w, height: h))
        anchors[i] = best
    }
    return anchors
}

package static func pieLegendRow(_ measure: DiagramTextMeasurer) -> CGFloat {
    grown(20, fontSize: labelFontSize, measure)
}

static func assignLayers(ids: [String], edges: [(String, String)]) -> [String: Int] {
    let longest = longestPathLayers(ids: ids, edges: edges)
    guard ids.count > 2, !edges.isEmpty else { return longest }

    // Index the graph. Parallel edges are kept (they weight the objective
    // like Gansner's multi-edges); self-edges never constrain layering.
    var indexOf: [String: Int] = [:]
    for (i, id) in ids.enumerated() where indexOf[id] == nil { indexOf[id] = i }
    let n = ids.count
    var edgeList: [(tail: Int, head: Int)] = []
    for (from, to) in edges {
        guard let u = indexOf[from], let v = indexOf[to], u != v else { continue }
        edgeList.append((u, v))
    }
    guard !edgeList.isEmpty else { return longest }

    var rank = [Int](repeating: 0, count: n)
    for (id, i) in indexOf { rank[i] = longest[id] ?? 0 }

    // Optimize each weakly-connected component independently (the tight
    // spanning tree needs a connected graph).
    var componentOf = [Int](repeating: -1, count: n)
    var componentCount = 0
    var adjacency = [[Int]](repeating: [], count: n)
    for (index, e) in edgeList.enumerated() {
        adjacency[e.tail].append(index)
        adjacency[e.head].append(index)
    }
    for start in 0..<n where componentOf[start] == -1 {
        var stack = [start]
        componentOf[start] = componentCount
        while let node = stack.popLast() {
            for ei in adjacency[node] {
                let other = edgeList[ei].tail == node ? edgeList[ei].head : edgeList[ei].tail
                if componentOf[other] == -1 { componentOf[other] = componentCount; stack.append(other) }
            }
        }
        componentCount += 1
    }

    for component in 0..<componentCount {
        let nodes = (0..<n).filter { componentOf[$0] == component }
        guard nodes.count > 1 else { continue }
        let localEdges = edgeList.indices.filter { componentOf[edgeList[$0].tail] == component }
        guard !localEdges.isEmpty else { continue }
        if !networkSimplex(nodes: nodes, edgeIndices: localEdges, edges: edgeList,
                           rank: &rank, adjacency: adjacency) {
            // Optimizer bailed (iteration cap): restore longest-path ranks
            // for this component — feasible and known-good.
            for i in nodes { rank[i] = longest[ids[i]] ?? 0 }
        }
    }

    // Normalize each component to start at layer 0 (matches the old
    // behavior, which every caller assumes).
    var minOfComponent = [Int](repeating: .max, count: componentCount)
    for i in 0..<n { minOfComponent[componentOf[i]] = min(minOfComponent[componentOf[i]], rank[i]) }
    var result: [String: Int] = [:]
    for (id, i) in indexOf { result[id] = rank[i] - minOfComponent[componentOf[i]] }
    // Duplicated ids (shouldn't happen, but the old code tolerated them):
    for id in ids where result[id] == nil { result[id] = 0 }
    return result
}

static func longestPathLayers(ids: [String], edges: [(String, String)]) -> [String: Int] {
    var layerOf: [String: Int] = [:]
    for id in ids { layerOf[id] = 0 }
    for _ in 0..<(ids.count + 1) {
        var changed = false
        for (from, to) in edges {
            guard let a = layerOf[from], let b = layerOf[to] else { continue }
            if b < a + 1 { layerOf[to] = a + 1; changed = true }
        }
        if !changed { break }
    }
    return layerOf
}

private static func networkSimplex(
    nodes: [Int], edgeIndices: [Int], edges: [(tail: Int, head: Int)],
    rank: inout [Int], adjacency: [[Int]]
) -> Bool {
    let inComponent = Set(nodes)
    func slack(_ ei: Int) -> Int { rank[edges[ei].head] - rank[edges[ei].tail] - 1 }

    // --- feasible tight tree ------------------------------------------
    // Grow a spanning tree of slack-0 edges; when stuck, shift the tree's
    // ranks by the minimum slack of any edge leaving it, which tightens
    // that edge without breaking feasibility.
    var inTree = Set<Int>()          // node set
    var treeEdges = Set<Int>()       // edge-index set
    inTree.insert(nodes[0])
    while inTree.count < nodes.count {
        // Add every tight edge reachable from the current tree.
        var grew = true
        while grew {
            grew = false
            // Sorted iteration: Set order is unspecified, and layer
            // assignment must be bit-for-bit reproducible (ELK's
            // "consider model order" starts with determinism).
            for node in inTree.sorted() {
                for ei in adjacency[node] where !treeEdges.contains(ei) {
                    let e = edges[ei]
                    guard inComponent.contains(e.tail), inComponent.contains(e.head) else { continue }
                    let other = e.tail == node ? e.head : e.tail
                    if !inTree.contains(other), slack(ei) == 0 {
                        inTree.insert(other); treeEdges.insert(ei); grew = true
                    }
                }
            }
        }
        if inTree.count == nodes.count { break }
        // Minimum-slack edge with exactly one endpoint in the tree.
        var best: (ei: Int, delta: Int)?
        for ei in edgeIndices {
            let e = edges[ei]
            let tailIn = inTree.contains(e.tail), headIn = inTree.contains(e.head)
            guard tailIn != headIn else { continue }
            let s = slack(ei)
            let delta = tailIn ? s : -s   // shift tree so this edge tightens
            if best == nil || abs(s) < abs(slack(best!.ei)) { best = (ei, delta) }
        }
        guard let found = best else { return false }   // disconnected?? bail
        for node in inTree { rank[node] += found.delta }
    }

    // --- optimize ------------------------------------------------------
    // Cut value of a tree edge = (edges tail-side → head-side) minus
    // (head-side → tail-side). Negative means the layering shrinks by
    // swapping it out. Recomputed from scratch each iteration — O(V·E),
    // fine at diagram scale (≤ maxEdges).
    func tailComponent(removing cut: Int) -> Set<Int> {
        var side = Set([edges[cut].tail])
        var stack = [edges[cut].tail]
        while let node = stack.popLast() {
            for ei in adjacency[node] where treeEdges.contains(ei) && ei != cut {
                let e = edges[ei]
                let other = e.tail == node ? e.head : e.tail
                if inComponent.contains(other), !side.contains(other) {
                    side.insert(other); stack.append(other)
                }
            }
        }
        return side
    }

    let cap = 8 * edgeIndices.count + 64
    for _ in 0..<cap {
        var swapped = false
        for cut in treeEdges.sorted() {
            let tailSide = tailComponent(removing: cut)
            var cutValue = 0
            for ei in edgeIndices {
                let e = edges[ei]
                if tailSide.contains(e.tail), !tailSide.contains(e.head) { cutValue += 1 }
                if !tailSide.contains(e.tail), tailSide.contains(e.head) { cutValue -= 1 }
            }
            guard cutValue < 0 else { continue }
            // Entering edge: head-side → tail-side with minimum slack.
            var enter: Int?
            for ei in edgeIndices where ei != cut {
                let e = edges[ei]
                if !tailSide.contains(e.tail), tailSide.contains(e.head) {
                    if enter == nil || slack(ei) < slack(enter!) { enter = ei }
                }
            }
            guard let entering = enter else { continue }
            let s = slack(entering)
            if s > 0 { for node in tailSide { rank[node] -= s } }
            treeEdges.remove(cut)
            treeEdges.insert(entering)
            swapped = true
            break
        }
        if !swapped { return true }   // optimal: no negative cut values
    }
    return false
}

public static func layout(_ d: SankeyDiagram, measure: DiagramTextMeasurer) -> SankeyLayout {
    let margin: CGFloat = 16
    let thickness: CGFloat = 16
    let columnSpacing: CGFloat = 230
    let nodeGap: CGFloat = 12
    let labelSize: Double = 11
    let labelPad: CGFloat = 6
    let minBarHeight: CGFloat = 6

    let names = d.nodes
    let n = names.count
    guard n > 0 else {
        return SankeyLayout(size: CGSize(width: 120, height: 80), nodes: [], links: [])
    }
    // Keyed by first occurrence; `uniquingKeysWith` because a hand-built
    // SankeyDiagram may repeat a node name and a public entry point must
    // not trap on malformed input.
    let index = Dictionary(names.enumerated().map { ($1, $0) }, uniquingKeysWith: { first, _ in first })

    // Flow totals and predecessor lists.
    var inValue = [Double](repeating: 0, count: n)
    var outValue = [Double](repeating: 0, count: n)
    var incoming: [[Int]] = Array(repeating: [], count: n)
    for link in d.links {
        guard let s = index[link.source], let t = index[link.target] else { continue }
        outValue[s] += link.value
        inValue[t] += link.value
        incoming[t].append(s)
    }
    let nodeValue = (0..<n).map { max(inValue[$0], outValue[$0], 0.0001) }

    // Longest-path depth from sources, with a cycle guard.
    var depthMemo = [Int?](repeating: nil, count: n)
    var visiting = [Bool](repeating: false, count: n)
    func depth(_ i: Int) -> Int {
        if let cached = depthMemo[i] { return cached }
        if visiting[i] { return 0 }
        visiting[i] = true
        var best = 0
        for p in incoming[i] { best = max(best, depth(p) + 1) }
        visiting[i] = false
        depthMemo[i] = best
        return best
    }
    var depths = (0..<n).map { depth($0) }
    let deepest = depths.max() ?? 0
    // Justify alignment (d3-sankey's default `nodeAlign`): a SINK — a node
    // with no outgoing flow — belongs in the RIGHTMOST column, not merely
    // at its longest path from a source. Without this, "Shipping"
    // (Crude Oil → Refined Fuels → Shipping) has depth 2 and floats in a
    // middle column instead of lining up on the right edge with the other
    // outputs (Useful Energy, Waste Heat, Grid Losses), exactly as Clint
    // spotted. `outValue[i] == 0` ⇔ the node emits nothing ⇔ it's a sink.
    for i in 0..<n where outValue[i] <= 0 { depths[i] = deepest }
    let maxDepth = depths.max() ?? 0

    // Group node indices by column, preserving first-appearance order.
    var columns: [[Int]] = Array(repeating: [], count: maxDepth + 1)
    for i in 0..<n { columns[depths[i]].append(i) }

    // Crossing minimization: reorder each column by the barycenter of its
    // neighbours' positions in the adjacent column, alternating forward and
    // backward sweeps. Without this the columns keep their arbitrary
    // first-appearance order and the bands weave over each other.
    var outgoing: [[Int]] = Array(repeating: [], count: n)
    for link in d.links {
        if let s = index[link.source], let t = index[link.target] { outgoing[s].append(t) }
    }
    var posInCol = [Int](repeating: 0, count: n)
    func recordPositions() {
        for col in columns { for (k, i) in col.enumerated() { posInCol[i] = k } }
    }
    recordPositions()
    func barycenter(_ i: Int, _ neighbours: [[Int]], inColumn c: Int) -> Double {
        let ns = neighbours[i].filter { depths[$0] == c }
        guard !ns.isEmpty else { return Double(posInCol[i]) }
        return Double(ns.reduce(0) { $0 + posInCol[$1] }) / Double(ns.count)
    }
    if maxDepth >= 1 {
        for _ in 0..<4 {
            for c in 1...maxDepth {
                columns[c].sort { barycenter($0, incoming, inColumn: c - 1) < barycenter($1, incoming, inColumn: c - 1) }
                recordPositions()
            }
            for c in stride(from: maxDepth - 1, through: 0, by: -1) {
                columns[c].sort { barycenter($0, outgoing, inColumn: c + 1) < barycenter($1, outgoing, inColumn: c + 1) }
                recordPositions()
            }
        }
    }

    // Choose a value→pixel scale so the busiest column fits a target height.
    let targetHeight: CGFloat = 520
    var maxColValue = 0.0001
    for col in columns { maxColValue = max(maxColValue, col.reduce(0) { $0 + nodeValue[$1] }) }
    let maxColCount = columns.map(\.count).max() ?? 1
    var scale = (targetHeight - CGFloat(max(maxColCount - 1, 0)) * nodeGap) / CGFloat(maxColValue)
    // A low floor: `minBarHeight` already guarantees tiny nodes stay
    // visible, so a big 3px/unit floor only inflates the canvas into a
    // tall, cramped portrait. Keep it small so the plot stays landscape.
    scale = min(max(scale, 1.2), 60)

    func barHeight(_ i: Int) -> CGFloat { max(CGFloat(nodeValue[i]) * scale, minBarHeight) }

    // Column pixel heights and the tallest (content) height.
    let colHeights: [CGFloat] = columns.map { col in
        guard !col.isEmpty else { return 0 }
        return CGFloat(col.count - 1) * nodeGap + col.reduce(CGFloat(0)) { $0 + barHeight($1) }
    }
    let contentHeight = max(colHeights.max() ?? thickness, thickness)

    // Horizontal room for outboard labels.
    func maxLabelWidth(_ col: [Int]) -> CGFloat {
        col.reduce(CGFloat(0)) { max($0, measure(names[$1], labelSize).width) }
    }
    let leftRoom = maxLabelWidth(columns.first ?? []) + labelPad
    let rightRoom = maxLabelWidth(columns.last ?? []) + labelPad
    let originX = margin + leftRoom
    let topOffset = margin

    // ---- Coordinate assignment: a faithful port of d3-sankey's
    // computeNodeBreadths (github.com/d3/d3-sankey). Node bar heights are
    // value*scale; y-positions start stacked per column, then relax toward
    // the LINK-ATTACHMENT point (targetTop/sourceTop), weighted by
    // value × layer-distance, over `iterations` passes — each doing
    // relaxRightToLeft then relaxLeftToRight, re-sorting links by breadth,
    // with GENTLE α-damped centre-outward collision resolution that
    // preserves the relaxation (a hard re-stack, which I did before, undoes
    // it and reads worse). This is the algorithm every real Sankey uses. ----
    let iterations = 32
    let py = Swift.min(nodeGap, contentHeight / CGFloat(Swift.max(maxColCount - 1, 1)))
    let yTop = topOffset, yBot = topOffset + contentHeight
    func nh(_ i: Int) -> CGFloat { barHeight(i) }
    var y0 = [CGFloat](repeating: 0, count: n)   // node top edge
    for col in columns {
        let colH = col.reduce(CGFloat(0)) { $0 + nh($1) } + CGFloat(Swift.max(col.count - 1, 0)) * py
        var y = yTop + (contentHeight - colH) / 2
        for i in col { y0[i] = y; y += nh(i) + py }
    }

    // Directed links with pixel width; per-node out/in lists (re-sorted by
    // the connected node's breadth each pass, so the attachment maths track).
    struct DL { let other: Int; let width: CGFloat }
    var srcLinks = [[DL]](repeating: [], count: n)   // outgoing (this = source)
    var tgtLinks = [[DL]](repeating: [], count: n)   // incoming (this = target)
    for link in d.links {
        guard let s = index[link.source], let t = index[link.target] else { continue }
        let w = CGFloat(link.value) * scale
        srcLinks[s].append(DL(other: t, width: w))
        tgtLinks[t].append(DL(other: s, width: w))
    }

    // Ideal y0 for `t` so its link from `s` lines up (and vice versa).
    func targetTop(_ s: Int, _ t: Int) -> CGFloat {
        var y = y0[s] - CGFloat(srcLinks[s].count - 1) * py / 2
        for dl in srcLinks[s] { if dl.other == t { break }; y += dl.width + py }
        for dl in tgtLinks[t] { if dl.other == s { break }; y -= dl.width }
        return y
    }
    func sourceTop(_ s: Int, _ t: Int) -> CGFloat {
        var y = y0[t] - CGFloat(tgtLinks[t].count - 1) * py / 2
        for dl in tgtLinks[t] { if dl.other == s { break }; y += dl.width + py }
        for dl in srcLinks[s] { if dl.other == t { break }; y -= dl.width }
        return y
    }
    func resolveCollisions(_ col: [Int], _ alpha: CGFloat) {
        let nodes = col.sorted { y0[$0] < y0[$1] }
        guard !nodes.isEmpty else { return }
        func topToBottom(_ startY: CGFloat, _ from: Int) {
            var y = startY, i = from
            while i < nodes.count {
                let dy = (y - y0[nodes[i]]) * alpha
                if dy > 1e-6 { y0[nodes[i]] += dy }
                y = y0[nodes[i]] + nh(nodes[i]) + py; i += 1
            }
        }
        func bottomToTop(_ startY: CGFloat, _ from: Int) {
            var y = startY, i = from
            while i >= 0 {
                let dy = (y0[nodes[i]] + nh(nodes[i]) - y) * alpha
                if dy > 1e-6 { y0[nodes[i]] -= dy }
                y = y0[nodes[i]] - py; i -= 1
            }
        }
        let mid = nodes.count / 2
        bottomToTop(y0[nodes[mid]] - py, mid - 1)
        topToBottom(y0[nodes[mid]] + nh(nodes[mid]) + py, mid + 1)
        bottomToTop(yBot, nodes.count - 1)
        topToBottom(yTop, 0)
    }

    if maxDepth >= 1 {
        for iter in 0..<iterations {
            let alpha = pow(0.99, CGFloat(iter))
            // reorder links by the connected node's current breadth
            for i in 0..<n {
                srcLinks[i].sort { y0[$0.other] < y0[$1.other] }
                tgtLinks[i].sort { y0[$0.other] < y0[$1.other] }
            }
            // relaxRightToLeft: position each node from its outgoing links
            for c in stride(from: maxDepth - 1, through: 0, by: -1) {
                for s in columns[c] where !srcLinks[s].isEmpty {
                    var y: CGFloat = 0, w: CGFloat = 0
                    for dl in srcLinks[s] {
                        let v = dl.width * CGFloat(Swift.max(depths[dl.other] - depths[s], 1))
                        y += (sourceTop(s, dl.other)) * v; w += v
                    }
                    if w > 0 { y0[s] += (y / w - y0[s]) * alpha }
                }
                resolveCollisions(columns[c], alpha)
            }
            // relaxLeftToRight: position each node from its incoming links
            for c in 1...maxDepth {
                for t in columns[c] where !tgtLinks[t].isEmpty {
                    var y: CGFloat = 0, w: CGFloat = 0
                    for dl in tgtLinks[t] {
                        let v = dl.width * CGFloat(Swift.max(depths[t] - depths[dl.other], 1))
                        y += (targetTop(dl.other, t)) * v; w += v
                    }
                    if w > 0 { y0[t] += (y / w - y0[t]) * alpha }
                }
                resolveCollisions(columns[c], alpha)
            }
        }
    }
    // Final HARD collision pass per column (alpha = 1). The damped
    // per-iteration passes converge but can leave residual overlap; one
    // firm separation at the end guarantees no bars overlap and all stay
    // in-bounds — without the every-iteration re-stacking that flattened
    // the layout in my earlier attempt.
    for c in 0...maxDepth { resolveCollisions(columns[c], 1.0) }
    for i in 0..<n { y0[i] = Swift.min(Swift.max(y0[i], yTop), yBot - nh(i)) }

    var rects = [CGRect](repeating: .zero, count: n)
    for (c, col) in columns.enumerated() {
        let colX = originX + CGFloat(c) * columnSpacing
        for i in col { rects[i] = CGRect(x: colX, y: y0[i], width: thickness, height: nh(i)) }
    }

    // Bands: stack outgoing on each source's right edge, incoming on each
    // target's left edge, in link declaration order.
    //
    // A link whose target is more than one column past its source would,
    // as a straight source→target centerline, pass through the bars in the
    // skipped column(s). We give such links a routed centerline that climbs
    // into the node-free band above every bar, runs across, and drops back
    // down at the target — the vertical legs hug the source's right edge and
    // the target's left edge (never entering another bar), and the crossbar
    // rides above the tallest column's top, so the route clears every
    // intermediate node. Depth is a longest-path rank, so a target's column
    // is always strictly greater than its source's; `ct - cs >= 2` is
    // exactly the set of column-skipping links.
    let clearY = topOffset - 6   // above every bar (bars start at topOffset)
    // Stack each node's outgoing bands by their target's vertical position
    // and incoming bands by their source's — so bands leave and arrive in
    // the same order as the nodes they connect and don't cross at the bar
    // edges (the second half of untangling, after the column ordering).
    struct Flow { let li: Int; let s: Int; let t: Int; let w: CGFloat }
    var flows: [Flow] = []
    for (li, link) in d.links.enumerated() {
        guard let s = index[link.source], let t = index[link.target] else { continue }
        flows.append(Flow(li: li, s: s, t: t, w: CGFloat(link.value) * scale))
    }
    var sourceTopY = [Int: CGFloat](), targetTopY = [Int: CGFloat]()
    var srcOffset = [CGFloat](repeating: 0, count: n), tgtOffset = [CGFloat](repeating: 0, count: n)
    for s in 0..<n {
        for f in flows.filter({ $0.s == s }).sorted(by: { rects[$0.t].midY < rects[$1.t].midY }) {
            sourceTopY[f.li] = rects[s].minY + srcOffset[s]; srcOffset[s] += f.w
        }
    }
    for t in 0..<n {
        for f in flows.filter({ $0.t == t }).sorted(by: { rects[$0.s].midY < rects[$1.s].midY }) {
            targetTopY[f.li] = rects[t].minY + tgtOffset[t]; tgtOffset[t] += f.w
        }
    }
    var links: [SankeyLayout.Link] = []
    for f in flows {
        let s = f.s, t = f.t, w = f.w
        let sTop = sourceTopY[f.li] ?? rects[s].minY
        let tTop = targetTopY[f.li] ?? rects[t].minY
        let sourceCenter = CGPoint(x: rects[s].maxX, y: sTop + w / 2)
        let targetCenter = CGPoint(x: rects[t].minX, y: tTop + w / 2)
        let route: [CGPoint]
        if depths[t] - depths[s] >= 2 {
            route = [
                sourceCenter,
                CGPoint(x: sourceCenter.x, y: clearY),
                CGPoint(x: targetCenter.x, y: clearY),
                targetCenter
            ]
        } else {
            route = [sourceCenter, targetCenter]
        }
        links.append(SankeyLayout.Link(
            sourceTop: CGPoint(x: rects[s].maxX, y: sTop),
            sourceBottom: CGPoint(x: rects[s].maxX, y: sTop + w),
            targetTop: CGPoint(x: rects[t].minX, y: tTop),
            targetBottom: CGPoint(x: rects[t].minX, y: tTop + w),
            colorIndex: s,
            route: route
        ))
    }

    // Node bars + their labels (leftmost column labels sit left, others
    // right, just outboard of the bar and centered on it).
    var nodes: [SankeyLayout.Node] = []
    for i in 0..<n {
        let r = rects[i]
        let labelWidth = measure(names[i], labelSize).width
        let labelCenter: CGPoint
        if depths[i] == 0 {
            labelCenter = CGPoint(x: r.minX - labelPad - labelWidth / 2, y: r.midY)
        } else {
            labelCenter = CGPoint(x: r.maxX + labelPad + labelWidth / 2, y: r.midY)
        }
        nodes.append(SankeyLayout.Node(
            label: names[i], rect: r, colorIndex: i, labelCenter: labelCenter
        ))
    }

    let rawWidth = originX + CGFloat(maxDepth) * columnSpacing + thickness + rightRoom + margin
    let rawHeight = topOffset + contentHeight + margin
    let size = CGSize(
        width: min(max(rawWidth, 80), 3800),
        height: min(max(rawHeight, 60), 3800)
    )
    return SankeyLayout(size: size, nodes: nodes, links: links)
}

public static func layout(_ diagram: SwimlaneDiagram, measure: DiagramTextMeasurer) -> SwimlaneLayout {
    let margin: CGFloat = 14
    let gutter: CGFloat = grown(30, fontSize: 10, measure)    // lane label gutter (rotated text)
    let columnGap: CGFloat = grown(46, fontSize: labelFontSize, measure)   // edge labels sit between columns
    let rowGap: CGFloat = grown(14, fontSize: labelFontSize, measure)
    let lanePad: CGFloat = 16
    let boxHeight: CGFloat = grown(32, fontSize: nodeFontSize, measure)

    // 1. Global columns from the layered layering (back-edges stripped
    //    the same way the flowchart pipeline does: cycles must not wedge
    //    the solver).
    let ids = diagram.nodes.map(\.id)
    // Drop self-loops, find the back-edges of the remaining digraph, and
    // strip them so the layering solver only sees a DAG.
    let forwardCandidates = diagram.edges
        .filter { $0.from != $0.to }
        .map { ($0.from, $0.to) }
    let backEdges = backEdgeIndices(ids: ids, edges: forwardCandidates)
    let acyclic = forwardCandidates.enumerated()
        .filter { !backEdges.contains($0.offset) }
        .map { $0.element }
    let layerOf = assignLayers(ids: ids, edges: acyclic)

    // 2. Column widths: widest node in each column.
    func nodeSize(_ node: SwimlaneDiagram.Node) -> CGSize {
        let text = measure(node.label, nodeFontSize)
        let extra: CGFloat = node.shape == .diamond ? 34 : 22
        return CGSize(width: text.width + extra, height: boxHeight)
    }
    let columns = (layerOf.values.max() ?? 0) + 1
    var columnWidth = [CGFloat](repeating: 64, count: columns)
    for node in diagram.nodes {
        let column = layerOf[node.id] ?? 0
        columnWidth[column] = max(columnWidth[column], nodeSize(node).width)
    }
    var columnX = [CGFloat](repeating: 0, count: columns)
    var x = margin + gutter
    for c in 0..<columns {
        columnX[c] = x
        x += columnWidth[c] + columnGap
    }
    let contentRight = x - columnGap

    // 3. Lane bands: height = tallest stack of same-lane same-column
    //    nodes, at least one row.
    var stacks: [String: [Int: [SwimlaneDiagram.Node]]] = [:]
    for node in diagram.nodes {
        stacks[node.laneID, default: [:]][layerOf[node.id] ?? 0, default: []].append(node)
    }
    var lanes: [SwimlaneLayout.Lane] = []
    var laneY: [String: CGFloat] = [:]
    var y = margin
    for lane in diagram.lanes {
        let deepest = stacks[lane.id]?.values.map(\.count).max() ?? 1
        let height = lanePad * 2 + CGFloat(deepest) * boxHeight + CGFloat(deepest - 1) * rowGap
        lanes.append(.init(label: lane.label,
                           band: CGRect(x: margin, y: y,
                                        width: contentRight - margin, height: height)))
        laneY[lane.id] = y
        y += height + 4
    }

    // 4. Place nodes: centred in their column, stacked in their lane.
    var placed: [String: CGRect] = [:]
    var nodes: [SwimlaneLayout.Node] = []
    for lane in diagram.lanes {
        guard let byColumn = stacks[lane.id], let bandY = laneY[lane.id] else { continue }
        for (column, group) in byColumn.sorted(by: { $0.key < $1.key }) {
            for (row, node) in group.enumerated() {
                let size = nodeSize(node)
                let frame = CGRect(
                    x: columnX[column] + (columnWidth[column] - size.width) / 2,
                    y: bandY + lanePad + CGFloat(row) * (boxHeight + rowGap),
                    width: size.width, height: size.height)
                placed[node.id] = frame
                nodes.append(.init(id: node.id, label: node.label,
                                   shape: node.shape, frame: frame))
            }
        }
    }

    // 5. Edges: right edge to left edge; same-row edges run straight,
    //    everything else takes a mid-gap elbow. Backward edges loop via
    //    the gap below the deeper node.
    var edges: [SwimlaneLayout.Edge] = []
    for edge in diagram.edges {
        guard let a = placed[edge.from], let b = placed[edge.to] else { continue }
        var points: [CGPoint]
        if a.maxX <= b.minX {
            let start = CGPoint(x: a.maxX, y: a.midY)
            let end = CGPoint(x: b.minX, y: b.midY)
            if abs(start.y - end.y) < 0.5 {
                points = [start, end]
            } else {
                let midX = (start.x + end.x) / 2
                points = [start, CGPoint(x: midX, y: start.y),
                          CGPoint(x: midX, y: end.y), end]
            }
        } else {
            // Backward or same-column: route below both boxes.
            let below = max(a.maxY, b.maxY) + rowGap
            points = [CGPoint(x: a.midX, y: a.maxY),
                      CGPoint(x: a.midX, y: below),
                      CGPoint(x: b.midX, y: below),
                      CGPoint(x: b.midX, y: b.maxY)]
        }
        var labelCenter: CGPoint?
        if edge.label != nil {
            let mid = points.count == 2
                ? CGPoint(x: (points[0].x + points[1].x) / 2, y: points[0].y - 9)
                : CGPoint(x: points[1].x, y: (points[1].y + points[2].y) / 2)
            labelCenter = mid
        }
        edges.append(.init(points: points, label: edge.label,
                           dashed: edge.dashed, labelCenter: labelCenter))
    }

    return SwimlaneLayout(
        size: CGSize(width: contentRight + margin, height: y - 4 + margin),
        lanes: lanes, nodes: nodes, edges: edges)
}

private func topologicalOrder(linkedParents: [[Int]]) -> [Int]? {
    let n = linkedParents.count
    var indegree = [Int](repeating: 0, count: n)
    var children = [[Int]](repeating: [], count: n)
    for (child, parents) in linkedParents.enumerated() {
        for p in parents {
            children[p].append(child)
            indegree[child] += 1
        }
    }
    var ready: [Int] = []
    for i in 0..<n where indegree[i] == 0 { ready.append(i) }   // ascending
    var order: [Int] = []
    order.reserveCapacity(n)
    var head = 0
    while head < ready.count {
        let node = ready[head]; head += 1
        order.append(node)
        for child in children[node] {
            indegree[child] -= 1
            if indegree[child] == 0 {
                // Insert keeping `ready[head...]` ascending (lowest emits next).
                var lo = head, hi = ready.count
                while lo < hi {
                    let mid = (lo + hi) / 2
                    if ready[mid] < child { lo = mid + 1 } else { hi = mid }
                }
                ready.insert(child, at: lo)
            }
        }
    }
    return order.count == n ? order : nil       // short ⇒ a cycle remains
}

private func assignBranches(order: [Int], records: [RawRecord],
                            firstParentOf: [Int?]) -> [String] {
    let n = order.count
    var branch = [String](repeating: defaultBranch, count: n)
    var decorated = [Bool](repeating: false, count: n)
    for (fi, rawIdx) in order.enumerated() {
        if let b = records[rawIdx].branch {
            branch[fi] = b
            decorated[fi] = true
        } else if let fp = firstParentOf[fi] {
            branch[fi] = branch[fp]
        }
    }
    var claimed = decorated
    for fi in stride(from: n - 1, through: 0, by: -1) {
        guard decorated[fi] else { continue }
        let b = branch[fi]
        var cur = firstParentOf[fi]
        while let p = cur, !claimed[p] {
            branch[p] = b
            claimed[p] = true
            cur = firstParentOf[p]
        }
    }
    return branch
}

private static func assignRanks(nodes: [String], edges: [FlowEdge], reversed: Set<EdgeKey>) -> [String: Int] {
    // Build directed adjacency with reversal applied.
    var inDeg: [String: Int] = Dictionary(uniqueKeysWithValues: nodes.map { ($0, 0) })
    var outs: [String: [(target: String, length: Int)]] = [:]
    for e in edges {
        let key = EdgeKey(from: e.from, to: e.to)
        let from = reversed.contains(key) ? e.to : e.from
        let to = reversed.contains(key) ? e.from : e.to
        outs[from, default: []].append((to, max(1, e.length)))
        inDeg[to, default: 0] += 1
    }
    // Topological sort (Kahn's). Ties broken by first-appearance order for determinism.
    var queue: [String] = nodes.filter { (inDeg[$0] ?? 0) == 0 }
    var order: [String] = []
    var inDegCopy = inDeg
    while !queue.isEmpty {
        let u = queue.removeFirst()
        order.append(u)
        for (v, _) in outs[u] ?? [] {
            inDegCopy[v, default: 0] -= 1
            if inDegCopy[v] == 0 { queue.append(v) }
        }
    }
    // Fallback: any nodes left (shouldn't be, post-cycle-break) get appended.
    for n in nodes where !order.contains(n) { order.append(n) }
    // Rank = max(rank(pred) + length).
    var rank: [String: Int] = [:]
    for n in order { rank[n] = 0 }
    for u in order {
        let ru = rank[u] ?? 0
        for (v, len) in outs[u] ?? [] {
            rank[v] = max(rank[v] ?? 0, ru + len)
        }
    }
    return rank
}

private static func assignRankMinMax(_ g: DagreGraph) {
    guard g.isCompound else { return }

    var graphMaxRank = 0

    for v in g.nodes() {
        guard let node = g.node(v) else { continue }

        // If this node has a borderTop, it's a compound node
        // (borderTop is set by NestingGraph.run)
        if let borderTop = node.borderTop,
           let borderBottom = node.borderBottom,
           let topNode = g.node(borderTop),
           let bottomNode = g.node(borderBottom) {
            node.minRank = topNode.rank
            node.maxRank = bottomNode.rank
            graphMaxRank = max(graphMaxRank, bottomNode.rank)
        }
    }

    // Store max rank on graph options
    // Note: LayoutOptions doesn't have maxRank, but it's tracked internally
    // This matches the TS behavior: g.graph().maxRank = maxRank
    _ = g.graph() as? LayoutOptions
}

private static func treeDepths(_ g: DagreGraph) -> [String: Int] {
    var depths: [String: Int] = [:]

    func dfs(_ v: String, depth: Int) {
        depths[v] = depth

        if let children = g.children(v), !children.isEmpty {
            for child in children {
                dfs(child, depth: depth + 1)
            }
        }
    }

    // Start from root children
    if let children = g.children(nil) {
        for child in children {
            dfs(child, depth: 1)
        }
    }

    return depths
}

public static func count(_ g: DagreGraph, layering: [[String]]) -> Int {
    var cc = 0
    for i in 1..<layering.count {
        cc += twoLayerCrossCount(g, northLayer: layering[i - 1], southLayer: layering[i])
    }
    return cc
}

private static func twoLayerCrossCount(
    _ g: DagreGraph,
    northLayer: [String],
    southLayer: [String]
) -> Int {
    guard !southLayer.isEmpty else { return 0 }

    // Build position map for south layer
    var southPos: [String: Int] = [:]
    for (i, v) in southLayer.enumerated() {
        southPos[v] = i
    }

    // Collect all edge entries (sorted by source, then target position)
    var southEntries: [(pos: Int, weight: Int)] = []

    for v in northLayer {
        guard let outEdges = g.outEdges(v) else { continue }

        // Get edges sorted by south position
        var entries: [(pos: Int, weight: Int)] = []
        for edge in outEdges {
            if let pos = southPos[edge.w] {
                let weight = g.edge(edge.id)?.weight ?? 1
                entries.append((pos, weight))
            }
        }
        entries.sort { $0.pos < $1.pos }
        southEntries.append(contentsOf: entries)
    }

    guard !southEntries.isEmpty else { return 0 }

    // Build the accumulator tree
    var firstIndex = 1
    while firstIndex < southLayer.count {
        firstIndex <<= 1
    }
    let treeSize = 2 * firstIndex - 1
    firstIndex -= 1
    var tree = Array(repeating: 0, count: treeSize)

    // Calculate weighted crossings using tree
    var cc = 0
    for entry in southEntries {
        var index = entry.pos + firstIndex
        tree[index] += entry.weight

        var weightSum = 0
        while index > 0 {
            if index % 2 == 1 {
                // Node is a left child, add right sibling
                weightSum += tree[index + 1]
            }
            index = (index - 1) >> 1
            tree[index] += entry.weight
        }

        cc += entry.weight * weightSum
    }

    return cc
}

public static func run(_ g: DagreGraph) -> [[String]] {
    var visited = Set<String>()

    // Get simple nodes (non-compound) sorted by rank
    let simpleNodes = g.nodes().filter { g.isLeaf($0) }

    guard let maxRank = simpleNodes.compactMap({ g.node($0)?.rank }).max() else {
        return []
    }

    // Initialize layers
    var layers: [[String]] = Array(repeating: [], count: maxRank + 1)

    func dfs(_ v: String) {
        guard !visited.contains(v) else { return }
        visited.insert(v)

        if let node = g.node(v) {
            let rank = node.rank
            if rank >= 0 && rank < layers.count {
                layers[rank].append(v)
            }
        }

        // Continue DFS to successors
        if let successors = g.successors(v) {
            for w in successors {
                dfs(w)
            }
        }
    }

    // Sort nodes by rank and process via DFS
    let orderedVs = simpleNodes.sorted { (a, b) in
        (g.node(a)?.rank ?? 0) < (g.node(b)?.rank ?? 0)
    }

    for v in orderedVs {
        dfs(v)
    }

    return layers
}

private static func buildLayerGraphs(_ g: DagreGraph, ranks: [Int], relationship: String) throws -> [(graph: Graph<BuildLayerGraph.LayerNodeLabel, BuildLayerGraph.LayerEdgeLabel>, root: String)] {
    // Build an index mapping from rank to the nodes with that rank
    // This helps avoid a quadratic search for all nodes with the same rank
    var nodesByRank: [Int: [String]] = [:]

    for v in g.nodes() {
        guard let node = g.node(v) else { continue }

        // Add node to its primary rank
        nodesByRank[node.rank, default: []].append(v)

        // If there is a range of ranks (compound nodes), add to each rank in the range
        // but skip node.rank which has already been added
        if let minRank = node.minRank, let maxRank = node.maxRank {
            for r in minRank...maxRank {
                if r != node.rank {
                    nodesByRank[r, default: []].append(v)
                }
            }
        }
    }

    var layerGraphs: [(graph: Graph<BuildLayerGraph.LayerNodeLabel, BuildLayerGraph.LayerEdgeLabel>, root: String)] = []
    for rank in ranks {
        let nodesWithRank = nodesByRank[rank] ?? []
        let result = try BuildLayerGraph.build(g, rank: rank, relationship: relationship, nodesWithRank: nodesWithRank)
        layerGraphs.append((graph: result.graph, root: result.root))
    }
    return layerGraphs
}

private static func sweepLayerGraphs(
    _ mainGraph: DagreGraph,
    layerGraphs: [(graph: Graph<BuildLayerGraph.LayerNodeLabel, BuildLayerGraph.LayerEdgeLabel>, root: String)],
    biasRight: Bool
) throws {
    // Constraint graph tracks ordering relationships between subgraphs
    let cg = Graph<Void, Void>()

    for lg in layerGraphs {
        // CRITICAL: Sync orders from main graph to layer graph before sorting
        // This is necessary because Swift's layer graphs have separate LayerNodeLabel objects,
        // unlike TypeScript where setDefaultNodeLabel returns references to the main graph's nodes.
        // Without this sync, barycenter calculations use stale order values from build time.
        for v in lg.graph.nodes() {
            if let mainOrder = mainGraph.node(v)?.order {
                lg.graph.node(v)?.order = mainOrder
            }
        }

        let sorted = SortSubgraph.sortLayerGraph(lg.graph, v: lg.root, cg: cg, biasRight: biasRight)

        // Apply order to layer graph nodes AND main graph nodes
        for (i, v) in sorted.vs.enumerated() {
            lg.graph.node(v)?.order = i
            // Also update the main graph's node order
            mainGraph.node(v)?.order = i
        }

        // Add subgraph constraints for next iteration
        try AddSubgraphConstraints.run(lg.graph, cg: cg, vs: sorted.vs)
    }
}

private static func assignOrder(_ g: DagreGraph, layering: [[String]]) {
    for layer in layering {
        for (i, v) in layer.enumerated() {
            g.node(v)?.order = i
        }
    }
}

public static func sortLayerGraph(
    _ g: Graph<BuildLayerGraph.LayerNodeLabel, BuildLayerGraph.LayerEdgeLabel>,
    v: String,
    cg: Graph<Void, Void>,
    biasRight: Bool
) -> Result {
    // Get movable children (exclude border nodes)
    var movable = g.children(v) ?? []
    let nodeLabel = g.node(v)

    // In layer graphs, borderLeft/borderRight are single node IDs (for this rank)
    let bl = nodeLabel?.borderLeft
    let br = nodeLabel?.borderRight

    if let bl = bl, let br = br {
        movable = movable.filter { $0 != bl && $0 != br }
    }

    // Calculate barycenters for movable nodes (with original indices)
    var entries = calculateLayerBarycenters(g, movable: movable)
    var subgraphs: [String: Result] = [:]

    // Recursively sort child subgraphs
    for i in 0..<entries.count {
        let entryV = entries[i].v
        if let children = g.children(entryV), !children.isEmpty {
            let subgraphResult = sortLayerGraph(g, v: entryV, cg: cg, biasRight: biasRight)
            subgraphs[entryV] = subgraphResult

            if subgraphResult.barycenter != nil {
                mergeBarycenters(&entries[i], other: subgraphResult)
            }
        }
    }

    // Resolve conflicts using constraint graph
    let resolved = resolveConflicts(entries, cg: cg)

    // Sort entries by barycenter
    let sorted = sortEntries(resolved, biasRight: biasRight)

    // Expand subgraph results
    let expandedVs = sorted.flatMap { v -> [String] in
        if let subResult = subgraphs[v] {
            return subResult.vs
        }
        return [v]
    }

    // Build result with borders
    var result = Result(vs: expandedVs)

    if let bl = bl, let br = br {
        result.vs = [bl] + result.vs + [br]

        // Update barycenter to include border nodes
        if let preds = g.predecessors(bl), !preds.isEmpty,
           let blPred = g.node(preds[0]),
           let brPreds = g.predecessors(br), !brPreds.isEmpty,
           let brPred = g.node(brPreds[0]) {

            if result.barycenter == nil {
                result.barycenter = 0
                result.weight = 0
            }

            let bc = result.barycenter ?? 0
            let weight = result.weight
            let blOrder = blPred.order
            let brOrder = brPred.order

            result.barycenter = (bc * Double(weight) + Double(blOrder + brOrder)) / Double(weight + 2)
            result.weight = weight + 2
        }
    }

    // Calculate final barycenter from resolved entries if not set
    if result.barycenter == nil {
        var totalSum: Double = 0
        var totalWeight: Int = 0
        for entry in resolved {
            if let bc = entry.barycenter {
                totalSum += bc * Double(entry.weight)
                totalWeight += entry.weight
            }
        }
        if totalWeight > 0 {
            result.barycenter = totalSum / Double(totalWeight)
            result.weight = totalWeight
        }
    }

    return result
}

private static func calculateLayerBarycenters(
    _ g: Graph<BuildLayerGraph.LayerNodeLabel, BuildLayerGraph.LayerEdgeLabel>,
    movable: [String]
) -> [Barycenter.Entry] {
    return movable.enumerated().map { (index, v) in
        guard let inEdges = g.inEdges(v), !inEdges.isEmpty else {
            return Barycenter.Entry(v: v, i: index)
        }

        var sum: Double = 0
        var weight: Int = 0

        for edge in inEdges {
            let neighbor = edge.v
            guard let neighborLabel = g.node(neighbor) else { continue }
            let edgeWeight = g.edge(edge.id)?.weight ?? 1

            sum += Double(edgeWeight * neighborLabel.order)
            weight += edgeWeight
        }

        if weight > 0 {
            return Barycenter.Entry(v: v, barycenter: sum / Double(weight), weight: weight, i: index)
        } else {
            return Barycenter.Entry(v: v, i: index)
        }
    }
}

private static func shiftRanks(_ t: Tree, _ g: DagreGraph, delta: Int) {
    for v in t.nodes() {
        if let label = g.node(v) {
            label.rank += delta
        }
    }
}

public static func run(_ g: DagreGraph) {
    var visited = Set<String>()

    func dfs(_ v: String) -> Int {
        guard let label = g.node(v) else { return 0 }

        if visited.contains(v) {
            return label.rank
        }

        visited.insert(v)

        // Get minimum rank based on successors
        var minSuccRank = Int.max
        if let outEdges = g.outEdges(v) {
            for edge in outEdges {
                let succRank = dfs(edge.w)
                let minlen = g.edge(edge.id)?.minlen ?? 1
                minSuccRank = min(minSuccRank, succRank - minlen)
            }
        }

        // If no successors, this is a sink - use rank 0
        // Otherwise, use minimum successor rank - minlen
        let rank = minSuccRank == Int.max ? 0 : minSuccRank
        label.rank = rank

        return rank
    }

    // Process only from source nodes (TypeScript line 58: g.sources().forEach(dfs))
    // Sources are nodes with no incoming edges
    for v in g.sources() {
        _ = dfs(v)
    }

    // NOTE: TypeScript's longestPath does NOT normalize ranks
    // normalization is done elsewhere if needed
}

public static func run(_ g: DagreGraph) throws {
    // Simplify the graph for the algorithm
    let simplified = try GraphUtil.simplify(g)

    // Initialize ranks using longest path
    LongestPath.run(simplified)

    // Build initial feasible spanning tree
    let t = try FeasibleTree.build(simplified)

    // Initialize low/lim values via postorder DFS
    initLowLimValues(t)

    // Initialize cut values for all tree edges
    initCutValues(t, simplified)

    // Pivot loop: find and replace edges with negative cut values
    while let leaveE = leaveEdge(t) {
        if let enterE = enterEdge(t, simplified, leaveE) {
            try exchangeEdges(t, simplified, leave: leaveE, enter: enterE)
        } else {
            break
        }
    }

    // Copy ranks back to original graph
    for v in g.nodes() {
        if let label = g.node(v), let simplifiedLabel = simplified.node(v) {
            label.rank = simplifiedLabel.rank
        }
    }
}

private static func updateRanks(_ t: FeasibleTree.Tree, _ g: DagreGraph) {
    // Find the root - TypeScript line 205: var root = t.nodes().find(v => !g.node(v).parent)
    // Note: TypeScript checks g.node(v).parent (the GRAPH node's parent), not t.node(v).parent
    guard let root = t.nodes().first(where: { g.node($0)?.parent == nil }) else { return }

    // Process nodes in preorder
    let nodes = preorder(t, root: root)

    // Skip the root itself (TypeScript line 207: vs = vs.slice(1))
    for v in nodes.dropFirst() {
        guard let tLabel = t.node(v),
              let parent = tLabel.parent,
              let gLabel = g.node(v),
              let parentGLabel = g.node(parent) else { continue }

        // Find the edge between v and parent in the original graph
        // TypeScript lines 210-218
        var flipped = false
        var edgeLabel = g.edge(v, parent)

        if edgeLabel == nil {
            edgeLabel = g.edge(parent, v)
            flipped = true
        }

        guard let edge = edgeLabel else { continue }

        // TypeScript line 218: g.node(v).rank = g.node(parent).rank + (flipped ? edge.minlen : -edge.minlen)
        gLabel.rank = parentGLabel.rank + (flipped ? edge.minlen : -edge.minlen)
    }
}

public static func buildLayerMatrix(_ g: DagreGraph) -> [[String]] {
    // Find max rank
    var maxRank = 0
    for v in g.nodes() {
        if let label = g.node(v) {
            maxRank = max(maxRank, label.rank)
        }
    }

    // Build layers
    var layers: [[String]] = Array(repeating: [], count: maxRank + 1)

    for v in g.nodes() {
        if let label = g.node(v) {
            let rank = label.rank
            // Guard against negative ranks which would cause index out of range
            if rank >= 0 && rank < layers.count {
                layers[rank].append(v)
            }
        }
    }

    // Sort each layer by order
    for i in 0..<layers.count {
        layers[i].sort { v1, v2 in
            (g.node(v1)?.order ?? 0) < (g.node(v2)?.order ?? 0)
        }
    }

    return layers
}

public static func maxRank(_ g: DagreGraph) -> Int {
    var max = Int.min
    for v in g.nodes() {
        if let label = g.node(v) {
            max = Swift.max(max, label.rank)
        }
    }
    return max
}

public static func normalizeRanks(_ g: DagreGraph) {
    var minRank = Int.max
    for v in g.nodes() {
        if let label = g.node(v), label.dummy == nil || label.dummy == .edge || label.dummy == .edgeLabel {
            minRank = min(minRank, label.rank)
        }
    }

    if minRank == Int.max { return }

    for v in g.nodes() {
        if let label = g.node(v) {
            label.rank -= minRank
        }
    }
}

public static func removeEmptyRanks(_ g: DagreGraph) {
    // Check if there are any compound nodes (nodes with children)
    // In TypeScript, these have rank=undefined, which causes Math.min to return NaN,
    // making the entire function do nothing. We match this by early return.
    if g.isCompound {
        for v in g.nodes() {
            if let children = g.children(v), !children.isEmpty {
                // Found a compound node - skip removeEmptyRanks to match TypeScript
                // In TypeScript, compound nodes have rank=undefined which causes Math.min
                // to return NaN, effectively skipping the entire function
                return
            }
        }
    }

    // Get ranks of all nodes
    var nodeRanks: [Int] = []
    for v in g.nodes() {
        if let label = g.node(v) {
            nodeRanks.append(label.rank)
        }
    }

    // Find minimum rank (offset)
    let offset = nodeRanks.min() ?? 0

    // Build layers array (sparse - some indices may be nil)
    var layers: [[String]?] = []
    for v in g.nodes() {
        if let label = g.node(v) {
            let rank = label.rank - offset
            // Guard against negative ranks
            if rank < 0 { continue }
            // Ensure layers array is large enough
            while layers.count <= rank {
                layers.append(nil)
            }
            if layers[rank] == nil {
                layers[rank] = []
            }
            layers[rank]?.append(v)
        }
    }

    // Get nodeRankFactor from graph options
    // This determines which empty ranks to preserve
    // With nodeRankFactor=1 (default), NO empty ranks are removed
    // Matches TypeScript: let nodeRankFactor = g.graph().nodeRankFactor;
    let nodeRankFactor = (g.graph() as? LayoutOptions)?.nodeRankFactor ?? 1

    // Calculate delta (how much to shift ranks)
    var delta = 0
    for (i, vs) in layers.enumerated() {
        if vs == nil {
            // Empty rank
            // TypeScript: if (vs === undefined && i % nodeRankFactor !== 0)
            // With nodeRankFactor=1: i % 1 = 0 for all i, so condition is NEVER true
            // This means NO empty ranks are removed when nodeRankFactor=1
            if nodeRankFactor != 0 && i % nodeRankFactor != 0 {
                delta -= 1
            }
        } else if delta != 0 {
            // Non-empty rank with accumulated delta - shift nodes
            for v in vs! {
                if let label = g.node(v) {
                    label.rank += delta
                }
            }
        }
    }
}

func longestPath(within scope: Set<TargetID>) -> (depth: Int, path: [TargetID]) {
    var memo: [TargetID: (depth: Int, path: [TargetID])] = [:]

    func visit(_ node: TargetID) -> (depth: Int, path: [TargetID]) {
        if let cached = memo[node] {
            return cached
        }
        var best: (depth: Int, path: [TargetID]) = (1, [node])
        for dependency in dependencies(of: node) where scope.contains(dependency) {
            let sub = visit(dependency)
            if sub.depth + 1 > best.depth {
                best = (sub.depth + 1, [node] + sub.path)
            }
        }
        memo[node] = best
        return best
    }

    var overall: (depth: Int, path: [TargetID]) = (0, [])
    for node in scope.sorted() {
        let candidate = visit(node)
        if candidate.depth > overall.depth {
            overall = candidate
        }
    }
    return overall
}

func depthLevels(within scope: Set<TargetID>) -> [Int: Set<TargetID>] {
    var memo: [TargetID: Int] = [:]

    func depth(of node: TargetID) -> Int {
        if let cached = memo[node] {
            return cached
        }
        var best = 1
        for dependency in dependencies(of: node) where scope.contains(dependency) {
            best = max(best, depth(of: dependency) + 1)
        }
        memo[node] = best
        return best
    }

    var levels: [Int: Set<TargetID>] = [:]
    for node in scope {
        levels[depth(of: node), default: []].insert(node)
    }
    return levels
}

func depth(of node: TargetID) -> Int {
    if let cached = memo[node] {
        return cached
    }
    var best = 1
    for dependency in dependencies(of: node) where scope.contains(dependency) {
        best = max(best, depth(of: dependency) + 1)
    }
    memo[node] = best
    return best
}

private static func makeLevelGroups(
    nodes: [SpiderGraphNode],
    edges: [SpiderGraphEdge],
    levels: [String: Int]
) -> [SpiderGraphLevelGroup] {
    var groupedNodes: [Int: [SpiderGraphNode]] = [:]
    for node in nodes {
        groupedNodes[levels[node.id] ?? 0, default: []].append(node)
    }

    return groupedNodes.keys.sorted().map { level in
        let levelNodes = (groupedNodes[level] ?? []).sorted(by: SpiderGraph.nodeSort)
        let internalEdgeCount = edges.reduce(into: 0) { count, edge in
            guard levels[edge.from] == level, levels[edge.to] == level else { return }
            count += 1
        }

        return SpiderGraphLevelGroup(
            level: level,
            nodes: levelNodes,
            internalEdgeCount: internalEdgeCount
        )
    }
}

private static func makeLevelEdges(
    edges: [SpiderGraphEdge],
    levels: [String: Int]
) -> [SpiderGraphLevelEdge] {
    var counts: [SpiderGraphLevelPair: Int] = [:]

    for edge in edges {
        let fromLevel = levels[edge.from] ?? 0
        let toLevel = levels[edge.to] ?? 0
        guard fromLevel != toLevel else { continue }
        counts[SpiderGraphLevelPair(fromLevel: fromLevel, toLevel: toLevel), default: 0] += 1
    }

    return counts.map { pair, count in
        SpiderGraphLevelEdge(
            fromLevel: pair.fromLevel,
            toLevel: pair.toLevel,
            edgeCount: count
        )
    }
    .sorted { lhs, rhs in
        if lhs.fromLevel != rhs.fromLevel { return lhs.fromLevel < rhs.fromLevel }
        return lhs.toLevel < rhs.toLevel
    }
}

private static func canvasLayerKinds(for nodes: [SpiderGraphNode]) -> [SpiderGraphCanvasLayerKind] {
    let internalLayerNames = Set<String>(
        nodes.compactMap { node in
            guard !node.isExternal, !node.isNewlyDiscovered else { return nil }
            return node.primaryLayer
        }
    )
    let orderedInternalLayerNames = internalLayerNames.sorted {
        $0.localizedCaseInsensitiveCompare($1) == .orderedAscending
    }

    var kinds: [SpiderGraphCanvasLayerKind] = orderedInternalLayerNames.map(SpiderGraphCanvasLayerKind.layer)
    if nodes.contains(where: { !$0.isExternal && $0.isNewlyDiscovered }) {
        kinds.append(.newModules)
    }
    if nodes.contains(where: { !$0.isExternal && !$0.isNewlyDiscovered && $0.primaryLayer == nil }) {
        kinds.append(SpiderGraphCanvasLayerKind.unclassified)
    }
    if nodes.contains(where: \.isExternal) {
        kinds.append(SpiderGraphCanvasLayerKind.external)
    }

    return kinds.isEmpty ? [SpiderGraphCanvasLayerKind.unclassified] : kinds
}

private static func canvasLayerKind(for node: SpiderGraphNode) -> SpiderGraphCanvasLayerKind {
    if node.isExternal {
        return .external
    }
    if node.isNewlyDiscovered {
        return .newModules
    }
    if let primaryLayer = node.primaryLayer {
        return .layer(primaryLayer)
    }
    return .unclassified
}

func maxReachableDepth(
    centeredOn rootID: String,
    direction: GraphDirection,
    includeExternal: Bool,
    layerFilter: SpiderGraphLayerFilter = .all
) -> Int {
    guard nodeMap[rootID] != nil else { return 0 }

    func allows(_ nodeID: String) -> Bool {
        guard let node = nodeMap[nodeID] else { return false }
        return matchesFilters(for: node, includeExternal: includeExternal, layerFilter: layerFilter) || nodeID == rootID
    }

    var maxDistance = 0
    if direction != .dependencies {
        maxDistance = max(maxDistance, bfs(from: rootID, adjacency: incoming, maxDepth: nil, allows: allows).values.max() ?? 0)
    }
    if direction != .dependents {
        maxDistance = max(maxDistance, bfs(from: rootID, adjacency: outgoing, maxDepth: nil, allows: allows).values.max() ?? 0)
    }
    return maxDistance
}

private func productRank(for node: SpiderGraphNode) -> Int {
    switch node.product?.lowercased() {
    case "app":
        return 0
    case "framework", "staticframework", "dynamicframework":
        return 1
    default:
        return 2
    }
}

private static func resolveLayerMetadata(
    from rawTags: [String],
    nodeName: String,
    projectPath: String?,
    product: String?,
    kind: String,
    isExternal: Bool
) -> ParsedLayerMetadata {
    let parsedTags = parseLayerMetadata(from: rawTags, nodeName: nodeName)
    guard parsedTags.primaryLayer == nil else {
        return parsedTags
    }

    guard !isExternal, kind.lowercased() == "target" else {
        return parsedTags
    }

    if let inferredByPath = inferLayerFromPath(projectPath) {
        return ParsedLayerMetadata(
            primaryLayer: inferredByPath,
            layerSource: .inferredPath,
            metadataTags: parsedTags.metadataTags,
            warnings: parsedTags.warnings
        )
    }

    if let inferredByName = inferLayerFromName(nodeName) {
        return ParsedLayerMetadata(
            primaryLayer: inferredByName,
            layerSource: .inferredName,
            metadataTags: parsedTags.metadataTags,
            warnings: parsedTags.warnings
        )
    }

    if let inferredByProduct = inferLayerFromProduct(product, kind: kind) {
        return ParsedLayerMetadata(
            primaryLayer: inferredByProduct,
            layerSource: .inferredProduct,
            metadataTags: parsedTags.metadataTags,
            warnings: parsedTags.warnings
        )
    }

    return parsedTags
}

private static func parseLayerMetadata(from rawTags: [String], nodeName: String) -> ParsedLayerMetadata {
    var layers: [String] = []
    var metadataTags: [String] = []

    for tag in rawTags {
        if let layer = layerName(from: tag) {
            layers.append(layer)
        } else {
            metadataTags.append(tag)
        }
    }

    let primaryLayer = layers.first
    let warnings: [String]
    if layers.count > 1, let primaryLayer {
        warnings = [
            "\(nodeName)은(는) 여러 layer 태그(\(layers.joined(separator: ", ")))를 가집니다. 첫 번째 값인 \(primaryLayer)만 사용합니다."
        ]
    } else {
        warnings = []
    }

    return ParsedLayerMetadata(
        primaryLayer: primaryLayer,
        layerSource: primaryLayer == nil ? nil : .metadataTag,
        metadataTags: metadataTags,
        warnings: warnings
    )
}

private static func layerName(from rawTag: String) -> String? {
    let tag = rawTag.trimmingCharacters(in: .whitespacesAndNewlines)
    let prefix = "layer:"
    guard tag.lowercased().hasPrefix(prefix) else { return nil }

    let rawLayer = String(tag.dropFirst(prefix.count))
    return normalizedLayerName(rawLayer)
}

private static func normalizedLayerName(_ rawLayer: String?) -> String? {
    guard let rawLayer else {
        return nil
    }

    let trimmed = rawLayer.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        return nil
    }
    return trimmed
}

private static func inferLayerFromPath(_ projectPath: String?) -> String? {
    guard let projectPath else { return nil }
    let normalizedPath = projectPath.lowercased()

    for rule in layerInferenceRules {
        if rule.pathMarkers.contains(where: { normalizedPath.contains($0) }) {
            return rule.layer
        }
    }

    return nil
}

private static func inferLayerFromName(_ name: String) -> String? {
    let normalizedName = name.lowercased()

    for rule in layerInferenceRules {
        if rule.nameMarkers.contains(where: { normalizedName.contains($0) }) {
            return rule.layer
        }
    }

    return nil
}

private static func inferLayerFromProduct(_ product: String?, kind: String) -> String? {
    let normalizedKind = kind.lowercased()
    if normalizedKind.contains("test") {
        return "testing"
    }

    guard let normalizedProduct = product?.lowercased() else { return nil }
    if normalizedProduct.contains("test") {
        return "testing"
    }
    if normalizedProduct == "app" || normalizedProduct.contains("application") {
        return "app"
    }

    return nil
}

func canEditLayerClassification(for node: SpiderGraphNode) -> Bool {
    guard let rootURL = snapshotRootURL(for: graph) else { return false }
    return ProjectLayerSnapshotStore.canPersist(node, rootURL: rootURL)
}

func availableLayerOptions(for node: SpiderGraphNode) -> [String] {
    let names = Set(
        graph.nodes.compactMap(\.primaryLayer)
        + graph.nodes.compactMap(\.suggestedLayer)
        + [node.primaryLayer, node.suggestedLayer].compactMap { $0 }
    )

    return names.sorted {
        $0.localizedCaseInsensitiveCompare($1) == .orderedAscending
    }
}

func applyLayerClassification(for nodeID: String, layerName: String?) {
    guard
        let node = graph.nodeMap[nodeID],
        let rootURL = snapshotRootURL(for: graph),
        ProjectLayerSnapshotStore.canPersist(node, rootURL: rootURL)
    else {
        return
    }

    let normalizedLayer = normalizedLayerName(layerName)
    let updatedNode = node.updatingClassification(
        primaryLayer: normalizedLayer,
        layerSource: .projectSnapshot,
        hasPersistedClassification: true
    )
    let updatedGraph = graph.replacingNodes(
        graph.nodes.map { $0.id == nodeID ? updatedNode : $0 }
    )

    do {
        try ProjectLayerSnapshotStore.syncSnapshot(for: updatedGraph, rootURL: rootURL)
        applyUpdatedGraph(updatedGraph)
        refreshNewModuleAlert(for: updatedGraph, shouldPresent: false)
        statusMessage = "레이어 분류를 저장했습니다."
    } catch {
        presentedError = .processFailed("레이어 분류를 저장하지 못했습니다. \(error.localizedDescription)")
        statusMessage = "레이어 분류 저장에 실패했습니다."
    }
}

func applySuggestedLayerClassification(for nodeID: String) {
    guard let node = graph.nodeMap[nodeID] else { return }
    applyLayerClassification(for: nodeID, layerName: node.suggestedLayer)
}

private func availableDepthOptions(for nodeID: String?) -> [GraphDepth] {
    guard let nodeID else { return [.all] }
    let maxDepth = cachedMaxReachableDepth(centeredOn: nodeID)
    guard maxDepth > 0 else { return [.all] }
    return (1...maxDepth).map { GraphDepth(maxDepth: $0) } + [.all]
}

private func relatedNodeConnectionSortRank(_ kind: SpiderGraphRelatedNodeConnectionKind) -> Int {
    switch kind {
    case .mutualDirect:
        return 0
    case .directDependency:
        return 1
    case .directDependent:
        return 2
    case .indirect:
        return 3
    }
}

