private func mirrorInLayerConstraintY(_ node: LNode) {
    let constraint = node.getProperty(InternalProperties.IN_LAYER_CONSTRAINT) as? InLayerConstraint ?? .NONE
    switch constraint {
    case .TOP:
        node.setProperty(InternalProperties.IN_LAYER_CONSTRAINT, value: InLayerConstraint.BOTTOM)
    case .BOTTOM:
        node.setProperty(InternalProperties.IN_LAYER_CONSTRAINT, value: InLayerConstraint.TOP)
    default:
        break
    }
}

private func transposeLayerConstraint(_ node: LNode) {
    let layerConstraint = node.getProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT) as? LayerConstraint ?? .NONE
    let inLayerConstraint = node.getProperty(InternalProperties.IN_LAYER_CONSTRAINT) as? InLayerConstraint ?? .NONE

    if layerConstraint == .FIRST_SEPARATE {
        node.setProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT, value: LayerConstraint.NONE)
        node.setProperty(InternalProperties.IN_LAYER_CONSTRAINT, value: InLayerConstraint.TOP)
    } else if layerConstraint == .LAST_SEPARATE {
        node.setProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT, value: LayerConstraint.NONE)
        node.setProperty(InternalProperties.IN_LAYER_CONSTRAINT, value: InLayerConstraint.BOTTOM)
    } else if inLayerConstraint == .TOP {
        node.setProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT, value: LayerConstraint.FIRST_SEPARATE)
        node.setProperty(InternalProperties.IN_LAYER_CONSTRAINT, value: InLayerConstraint.NONE)
    } else if inLayerConstraint == .BOTTOM {
        node.setProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT, value: LayerConstraint.LAST_SEPARATE)
        node.setProperty(InternalProperties.IN_LAYER_CONSTRAINT, value: InLayerConstraint.NONE)
    }
}

private func fixCoordinatesInLayer(_ layer: Layer, _ constraints: PortConstraints, _ graph: LGraph) {
    let padding = graph.getPadding()
    let offset = graph.getOffset()
    let graphActualSize = graph.getActualSize()

    var newActualGraphHeight = graphActualSize.y

    // First iteration: fix EAST and WEST dummy nodes (may change graph height)
    for node in layer.getNodes() {
        if node.getType() != .externalPort {
            continue
        }

        let extPortSide = node.getProperty(InternalProperties.EXT_PORT_SIDE) as? PortSide ?? .UNDEFINED
        let extPortSize = node.getProperty(InternalProperties.EXT_PORT_SIZE) as? KVector ?? KVector()
        let nodePosition = node.getPosition()

        // Set x coordinate
        switch extPortSide {
        case .EAST:
            nodePosition.x = graph.getSize().x + padding.right - offset.x
        case .WEST:
            nodePosition.x = -offset.x - padding.left
        default:
            break
        }

        // Set y coordinate
        var requiredActualGraphHeight = 0.0

        switch extPortSide {
        case .EAST, .WEST:
            if constraints == .FIXED_RATIO {
                let ratio = node.getProperty(InternalProperties.PORT_RATIO_OR_POSITION) as? Double ?? 0.0
                let anchorY = (node.getProperty(LayeredOptions.PORT_ANCHOR) as? KVector)?.y ?? 0.0
                nodePosition.y = graphActualSize.y * ratio - anchorY
                requiredActualGraphHeight = nodePosition.y + extPortSize.y
                node.borderToContentAreaCoordinates(false, true)
            } else if constraints == .FIXED_POS {
                let posOrRatio = node.getProperty(InternalProperties.PORT_RATIO_OR_POSITION) as? Double ?? 0.0
                let anchorY = (node.getProperty(LayeredOptions.PORT_ANCHOR) as? KVector)?.y ?? 0.0
                nodePosition.y = posOrRatio - anchorY
                requiredActualGraphHeight = nodePosition.y + extPortSize.y
                node.borderToContentAreaCoordinates(false, true)
            }
        default:
            break
        }

        newActualGraphHeight = max(newActualGraphHeight, requiredActualGraphHeight)
    }

    // Make the graph larger, if necessary
    graph.getSize().y += newActualGraphHeight - graphActualSize.y

    // Second iteration: fix NORTH and SOUTH dummies now that the graph's height is fixed
    for node in layer.getNodes() {
        if node.getType() != .externalPort {
            continue
        }

        let extPortSide = node.getProperty(InternalProperties.EXT_PORT_SIDE) as? PortSide ?? .UNDEFINED
        let nodePosition = node.getPosition()

        switch extPortSide {
        case .NORTH:
            nodePosition.y = -offset.y - padding.top
        case .SOUTH:
            nodePosition.y = graph.getSize().y + padding.bottom - offset.y
        default:
            break
        }
    }
}

private func correctSlantedEdgeSegmentsInLayer(_ layer: Layer) {
    for node in layer.getNodes() {
        if node.getType() != .externalPort {
            continue
        }

        let extPortSide = node.getProperty(InternalProperties.EXT_PORT_SIDE) as? PortSide

        if extPortSide == .EAST || extPortSide == .WEST {
            for edge in node.getConnectedEdges() {
                let bendPoints = edge.getBendPoints()

                if bendPoints.isEmpty {
                    // TODO: The edge has no bend points yet, but may still be slanted.
                    continue
                }

                // Correct slanted segment connected to the source port if it belongs to our node
                let sourcePort = edge.getSource()!
                if sourcePort.getNode() === node {
                    let firstBendPoint = bendPoints.getFirst()!
                    firstBendPoint.y = sourcePort.getAbsoluteAnchor().y
                }

                // Correct slanted segment connected to the target port if it belongs to our node
                let targetPort = edge.getTarget()!
                if targetPort.getNode() === node {
                    let lastBendPoint = bendPoints.getLast()!
                    lastBendPoint.y = targetPort.getAbsoluteAnchor().y
                }
            }
        }
    }
}

private func assignIdsToLayers(_ layeredGraph: LGraph) {
    for (index, layer) in layeredGraph.layers.enumerated() {
        layer.id = index
    }
}

private func calculateLayerWidths(_ layeredGraph: LGraph) {
    for layer in layeredGraph.layers {
        layerWidths[layer.id] = LGraphUtil.findMaxNonDummyNodeWidth(layer, respectNodeMargins: false)
    }
}

private func moveLabelsToLabelLayer(_ node: LNode, _ incoming: Bool, _ labelLayer: Layer) {
    let edges = incoming ? node.getIncomingEdges() : node.getOutgoingEdges()
    for edge in edges {
        guard let possibleLabelDummy = incoming ? edge.source?.node : edge.target?.node else { continue }
        if possibleLabelDummy.type == .label {
            possibleLabelDummy.setLayer(labelLayer)
        }
    }
}

private func updateOppositeNodeLayerConstraints(_ hiddenNode: LNode, _ oppositeNode: LNode) {
    if oppositeNode.hasProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT) {
        return
    }

    let hiddenConstraint = hiddenNode.getProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT) as? LayerConstraint ?? .NONE
    let current = oppositeNode.getProperty(
        org_eclipse_elk_alg_layered_intermediate_LayerConstraintPreprocessor.HIDDEN_NODE_CONNECTIONS
    ) as? HiddenNodeConnections ?? .NONE
    let connections = current.combine(hiddenConstraint)
    oppositeNode.setProperty(
        org_eclipse_elk_alg_layered_intermediate_LayerConstraintPreprocessor.HIDDEN_NODE_CONNECTIONS,
        value: connections
    )

    if oppositeNode.getConnectedEdges().first != nil {
        return
    }

    switch connections {
    case .FIRST_SEPARATE:
        oppositeNode.setProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT, value: LayerConstraint.FIRST)
    case .LAST_SEPARATE:
        oppositeNode.setProperty(LayeredOptions.LAYERING_LAYER_CONSTRAINT, value: LayerConstraint.LAST)
    default:
        break
    }
}

package func sourcePortConnectedToPreviousLayer(
    of node: org_eclipse_elk_alg_layered_graph_LNode
) -> org_eclipse_elk_alg_layered_graph_LPort? {
    for p in node.getPorts() where !p.getIncomingEdges().isEmpty {
        let edge = p.getIncomingEdges()[0]
        let sourceLayerId = edge.getSource()?.getNode()?.getLayer()?.id
        let nodeLayerId = node.getLayer()?.id
        if let sourceLayerId, let nodeLayerId, sourceLayerId == (nodeLayerId - 1) {
            return edge.getSource()
        }
    }
    return nil
}

package func getReferenceNodeInCurrentLayer(
    _ dummy: org_eclipse_elk_alg_layered_graph_LNode
) -> org_eclipse_elk_alg_layered_graph_LNode? {
    let currentLayerId = dummy.getLayer()?.id
    for edge in dummy.getIncomingEdges() {
        if let sourceNode = edge.getSource()?.getNode(), sourceNode.getLayer()?.id == currentLayerId {
            return sourceNode
        }
    }
    for edge in dummy.getOutgoingEdges() {
        if let targetNode = edge.getTarget()?.getNode(), targetNode.getLayer()?.id == currentLayerId {
            return targetNode
        }
    }
    return nil
}

private func checkReferenceLayer(
    _ layer: [org_eclipse_elk_alg_layered_graph_LNode],
    _ p1Node: org_eclipse_elk_alg_layered_graph_LNode,
    _ p2Node: org_eclipse_elk_alg_layered_graph_LNode,
    _ p1: org_eclipse_elk_alg_layered_graph_LPort,
    _ p2: org_eclipse_elk_alg_layered_graph_LPort
) -> Int {
    for node in layer {
        if node === p1Node {
            return -1
        } else if node === p2Node {
            return 1
        }
    }
    return 0
}

package func getApproximateLayerWidth(_ l: Layer) -> Double {
    return determineLayerWidth(l)
}

package func getApproximateLayeringWidth() -> Double {
    return getSumWidth()
}

package func getApproximateChunkBasedLayeringWidth(_ cuts: [Int]) -> Double {
    if cuts.isEmpty {
        return getApproximateLayeringWidth()
    }
    var width: Double = 0
    var lowIdx = 0
    for highIdx in cuts {
        width = max(width, determineChunkWidth(lowIdx, highIdx))
        lowIdx = highIdx
    }
    width = max(width, determineChunkWidth(lowIdx, graph.getLayers().count))
    return width
}

package func getApproximateLayerHeight(_ l: Layer) -> Double {
    return determineLayerHeight(l)
}

package func getApproximateLayeringHeight() -> Double {
    return getMaxHeight()
}

package func getApproximateChunkBasedLayeringHeight(_ cuts: [Int]) -> Double {
    if cuts.isEmpty {
        return 0
    }
    var height: Double = 0
    var lowIdx = 0
    for highIdx in cuts {
        height += determineChunkHeight(lowIdx, highIdx)
        lowIdx = highIdx
    }
    height += determineChunkHeight(lowIdx, graph.getLayers().count)
    return height
}

package func determineLayerWidth(_ l: Layer) -> Double {
    var maxW: Double = 0
    for n in l.getNodes() {
        let nW = n.getSize().x + n.getMargin().right + n.getMargin().left + spacing
        maxW = max(maxW, nW)
    }
    return maxW
}

package func determineLayerHeight(_ layer: Layer) -> Double {
    var lH: Double = 0
    for n in layer.getNodes() {
        lH += n.getSize().y + n.getMargin().bottom + n.getMargin().top + inLayerSpacing

        for inc in n.getIncomingEdges() {
            if let srcNode = inc.getSource()?.getNode(),
               srcNode.getType() == .NORTH_SOUTH_PORT {
                let originAny: Any? = srcNode.getProperty(
                    InternalProperties.ORIGIN
                )
                if let origin = originAny as? LNode {
                    lH += origin.getSize().y + origin.getMargin().bottom + origin.getMargin().top
                }
            }
        }
    }
    return lH
}

package func isCutAllowedForLayer(_ layer: Layer) -> Bool {
    // We only allow to cut between a pair of layers
    // if there is only one pair of nodes that is connected by 1 or more edges
    var cutAllowed = true
    var n1: LNode? = nil
    var n2: LNode? = nil

    outer:
    for tgt in layer.getNodes() {
        for e in tgt.getIncomingEdges() {
            // Check for different target
            if n1 != nil && n1 !== tgt {
                cutAllowed = false
                break outer
            }
            n1 = tgt
            // Check for different source
            if let src = e.getSource()?.getNode() {
                if n2 != nil && n2 !== src {
                    cutAllowed = false
                    break outer
                }
                n2 = src
            }
        }
    }
    return cutAllowed
}

package func hierarchicalLayout(_ lgraph: LGraph, _ monitor: IElkProgressMonitor) {
    // Innermost graphs first, root last
    let graphs = collectAllGraphsBottomUp(lgraph)
    reviewAndCorrectHierarchicalProcessors(lgraph, graphs)

    // Get processor list for each graph. Use index to track progress (simulates Java Iterator).
    var work = 0
    var graphsAndAlgorithms: [(graph: LGraph, processors: [AnyGraphProcessor], idx: Int)] = []

    for g in graphs {
        graphConfigurator.prepareGraphForLayout(g)
        let processors = g.getProperty(InternalProperties.PROCESSORS) as? [AnyGraphProcessor] ?? []
        work += processors.count
        graphsAndAlgorithms.append((g, processors, 0))
    }

    monitor.begin("Recursive hierarchical layout", Float(work))

    // Find the root graph entry (last in the list since innermost-first ordering)
    guard let rootIdx = graphsAndAlgorithms.lastIndex(where: { isRoot($0.graph) }) else {
        monitor.done()
        return
    }

    var slotIndex = 0

    // While root still has processors to run
    while graphsAndAlgorithms[rootIdx].idx < graphsAndAlgorithms[rootIdx].processors.count {
        // Layout from bottom up (innermost graphs first)
        for i in 0..<graphsAndAlgorithms.count {
            var idx = graphsAndAlgorithms[i].idx
            let processors = graphsAndAlgorithms[i].processors
            let graph = graphsAndAlgorithms[i].graph

            // Inner while: run consecutive non-hierarchy-aware processors until we hit
            // a hierarchy-aware one or exhaust the list (matches Java's inner while loop)
            while idx < processors.count {
                let processor = processors[idx]

                if !processor.isHierarchyAware {
                    // Regular processor: execute immediately
                    if let sub = monitor.subTask(1) { processor.process(graph, sub) }

                    idx += 1
                    slotIndex += 1

                } else if isRoot(graph) {
                    // Hierarchy-aware processor on root: execute it
                    if let sub = monitor.subTask(1) { processor.process(graph, sub) }

                    idx += 1
                    slotIndex += 1

                    // Continue operation with the graph at the bottom of the hierarchy
                    break

                } else {
                    // Non-root hierarchy-aware: skip past it (Java's iterator.next() consumed it)
                    // and pause execution until root graph has processed
                    idx += 1
                    break
                }
            }

            graphsAndAlgorithms[i] = (graph, processors, idx)
        }
    }

    monitor.done()
}

package func configureGraphProperties(_ lgraph: LGraph) {
    // check the bounds of some layout options

    let edgeSpacing = lgraph.getProperty(LayeredOptions.SPACING_EDGE_EDGE) as? Double ?? 0.0
    if edgeSpacing < GraphConfigurator.MIN_EDGE_SPACING {
        lgraph.setProperty(LayeredOptions.SPACING_EDGE_EDGE, GraphConfigurator.MIN_EDGE_SPACING)
    }

    let directionRaw = lgraph.getProperty(LayeredOptions.DIRECTION)
    let direction = directionRaw as? Direction ?? .UNDEFINED
    if direction == .UNDEFINED {
        lgraph.setProperty(LayeredOptions.DIRECTION, LGraphUtil.getDirection(lgraph))
    }
    // set the random number generator based on the random seed option
    let randomSeed: Int
    if let i = lgraph.getProperty(LayeredOptions.RANDOM_SEED) as? Int {
        randomSeed = i
    } else if let d = lgraph.getProperty(LayeredOptions.RANDOM_SEED) as? Double {
        randomSeed = Int(d)
    } else {
        randomSeed = 1  // Java .melk default is 1; 0 would create unseeded (non-deterministic) Random
    }
    if randomSeed == 0 {
        lgraph.setProperty(InternalProperties.RANDOM, Random())
    } else {
        lgraph.setProperty(InternalProperties.RANDOM, Random(seed: randomSeed))
    }

    let favorStraightness = lgraph.getProperty(LayeredOptions.NODE_PLACEMENT_FAVOR_STRAIGHT_EDGES) as? Bool
    if favorStraightness == nil {
        let edgeRouting = Self.resolveEdgeRouting(lgraph)
        lgraph.setProperty(LayeredOptions.NODE_PLACEMENT_FAVOR_STRAIGHT_EDGES, edgeRouting == .ORTHOGONAL)
    }

    // copy the port constraints to keep a list of original port constraints
    copyPortContraints(lgraph)

    // pre-calculate spacing information
    let spacings = Spacings(lgraph)
    lgraph.setProperty(InternalProperties.SPACINGS, spacings)
}

package func getPhaseIndependentLayoutProcessorConfiguration(_ lgraph: LGraph) -> LayoutProcessorConfiguration<LayeredPhases, LGraph>? {

    let graphProperties = lgraph.getProperty(InternalProperties.GRAPH_PROPERTIES) as? Set<GraphProperties> ?? []

    // Basic configuration
    var configuration = LayoutProcessorConfiguration<LayeredPhases, LGraph>.create(from: GraphConfigurator.BASELINE_PROCESSING_CONFIGURATION)

    // Hierarchical layout. 
    //  Note that the recursive graph layout engine made sure that at this point
    //  'INCLUDE_CHILDREN' has been propagated to all parent nodes with 'INHERIT'.
    //  Thus, every lgraph of the hierarchical lgraph structure is configured with the following additions. 
    let hierarchyHandling = lgraph.getProperty(LayeredOptions.HIERARCHY_HANDLING) as? HierarchyHandling ?? .INHERIT
    if hierarchyHandling == .INCLUDE_CHILDREN {
        configuration.addAll(GraphConfigurator.HIERARCHICAL_ADDITIONS)
    }

    // Port side processor, put to first slot only if requested and routing is orthogonal
    if lgraph.getProperty(LayeredOptions.FEEDBACK_EDGES) as? Bool ?? false {
        configuration.addBefore(LayeredPhases.P1_CYCLE_BREAKING, IntermediateProcessorStrategy.PORT_SIDE_PROCESSOR)
    } else {
        configuration.addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.PORT_SIDE_PROCESSOR)
    }

    // If the graph has a label manager, so add label management additions
    if lgraph.getProperty(LabelManagementOptions.LABEL_MANAGER) != nil {
        configuration.addAll(GraphConfigurator.LABEL_MANAGEMENT_ADDITIONS)
    }

    // If the graph should be laid out interactively or you really want it,
    // add the layers and positions to the nodes.
    if lgraph.getProperty(LayeredOptions.INTERACTIVE_LAYOUT) as? Bool ?? false ||
        lgraph.getProperty(LayeredOptions.GENERATE_POSITION_AND_LAYER_IDS) as? Bool ?? false {
        configuration.addAfter(LayeredPhases.P5_EDGE_ROUTING, IntermediateProcessorStrategy.CONSTRAINTS_POSTPROCESSOR)
    }

    // graph transformations for unusual layout directions
    let direction = lgraph.getProperty(LayeredOptions.DIRECTION) as? Direction ?? .RIGHT
    switch direction {
    case .LEFT, .DOWN, .UP:
        configuration
            .addBefore(LayeredPhases.P1_CYCLE_BREAKING, IntermediateProcessorStrategy.DIRECTION_PREPROCESSOR)
            .addAfter(LayeredPhases.P5_EDGE_ROUTING, IntermediateProcessorStrategy.DIRECTION_POSTPROCESSOR)
    default:
        // This is either RIGHT or UNDEFINED, which is just mapped to RIGHT. Either way, we
        // don't need any processors here
        break
    }

    // Additional dependencies
    if graphProperties.contains(.COMMENTS) {
        configuration
            .addBefore(LayeredPhases.P1_CYCLE_BREAKING, IntermediateProcessorStrategy.COMMENT_PREPROCESSOR)
            .addBefore(LayeredPhases.P4_NODE_PLACEMENT, IntermediateProcessorStrategy.COMMENT_NODE_MARGIN_CALCULATOR)
            .addAfter(LayeredPhases.P5_EDGE_ROUTING, IntermediateProcessorStrategy.COMMENT_POSTPROCESSOR)
    }

    // Node-Promotion application for reduction of dummy nodes after layering
    let nodePromotionStrategy = lgraph.getProperty(LayeredOptions.LAYERING_NODE_PROMOTION_STRATEGY) as? NodePromotionStrategy ?? .NONE
    if nodePromotionStrategy != .NONE {
        configuration.addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.NODE_PROMOTION)
    }

    // Preserve certain partitions during layering
    if graphProperties.contains(.PARTITIONS) {
        configuration.addBefore(LayeredPhases.P1_CYCLE_BREAKING, IntermediateProcessorStrategy.PARTITION_PREPROCESSOR)
        configuration.addBefore(LayeredPhases.P2_LAYERING, IntermediateProcessorStrategy.PARTITION_MIDPROCESSOR)
        configuration.addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.PARTITION_POSTPROCESSOR)
    }

    // Additional horizontal compaction depends on orthogonal edge routing
    let compactionStrategy = lgraph.getProperty(LayeredOptions.COMPACTION_POST_COMPACTION_STRATEGY) as? GraphCompactionStrategy ?? .NONE
    let edgeRouting = Self.resolveEdgeRouting(lgraph)
    if compactionStrategy != .NONE && edgeRouting != .POLYLINE {
        configuration.addAfter(LayeredPhases.P5_EDGE_ROUTING, IntermediateProcessorStrategy.HORIZONTAL_COMPACTOR)
    }

    // Move trees of high degree nodes to separate layers
    if lgraph.getProperty(LayeredOptions.HIGH_DEGREE_NODES_TREATMENT) as? Bool ?? false {
        configuration.addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.HIGH_DEGREE_NODE_LAYER_PROCESSOR)
    }

    // Introduce in-layer constraints to preserve the order of regular nodes
    if lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_SEMI_INTERACTIVE) as? Bool ?? false {
        configuration.addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.SEMI_INTERACTIVE_CROSSMIN_PROCESSOR)
    }

    // Configure greedy switch
    //  Note that in the case of hierarchical layout, the configuration may further be adjusted by
    //  ElkLayered#reviewAndCorrectHierarchicalProcessors(...)
    if GraphConfigurator.activateGreedySwitchFor(lgraph) {
        let greedySwitchType: GreedySwitchType
        if GraphConfigurator.isHierarchicalLayout(lgraph) {
            greedySwitchType = lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_GREEDY_SWITCH_HIERARCHICAL_TYPE) as? GreedySwitchType ?? .OFF
        } else {
            greedySwitchType = lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_GREEDY_SWITCH_TYPE) as? GreedySwitchType ?? .TWO_SIDED
        }
        let internalGreedyType = (greedySwitchType == .ONE_SIDED)
            ? IntermediateProcessorStrategy.ONE_SIDED_GREEDY_SWITCH
            : IntermediateProcessorStrategy.TWO_SIDED_GREEDY_SWITCH
        configuration.addBefore(LayeredPhases.P4_NODE_PLACEMENT, internalGreedyType)
    }

    switch lgraph.getProperty(LayeredOptions.LAYER_UNZIPPING_STRATEGY) as? String {
    case "ALTERNATING":
        configuration.addBefore(LayeredPhases.P4_NODE_PLACEMENT, IntermediateProcessorStrategy.ALTERNATING_LAYER_UNZIPPER)
    default:
        break
    }

    // Wrapping of graphs
    switch lgraph.getProperty(LayeredOptions.WRAPPING_STRATEGY) as? String {
    case "SINGLE_EDGE":
        configuration.addBefore(LayeredPhases.P4_NODE_PLACEMENT, IntermediateProcessorStrategy.SINGLE_EDGE_GRAPH_WRAPPER)
    case "MULTI_EDGE":
        configuration
            .addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.BREAKING_POINT_INSERTER)
            .addBefore(LayeredPhases.P4_NODE_PLACEMENT, IntermediateProcessorStrategy.BREAKING_POINT_PROCESSOR)
            .addAfter(LayeredPhases.P5_EDGE_ROUTING, IntermediateProcessorStrategy.BREAKING_POINT_REMOVER)
    default: // OFF
        break
    }

    if (lgraph.getProperty(LayeredOptions.CONSIDER_MODEL_ORDER_STRATEGY) as? OrderingStrategy ?? .NONE) != .NONE {
        configuration
            .addBefore(LayeredPhases.P3_NODE_ORDERING, IntermediateProcessorStrategy.SORT_BY_INPUT_ORDER_OF_MODEL)
    }

    return configuration
}

package static func activateGreedySwitchFor(_ lgraph: LGraph) -> Bool {

    // First, check the hierarchical case
    if isHierarchicalLayout(lgraph) {
        // Note that we only activate it for the root in the hierarchical case and rely on
        // ElkLayered#reviewAndCorrectHierarchicalProcessors(...) to properly set it for the whole hierarchy.
        // Also, interactive crossing minimization is not allowed/applicable for hierarchical layout
        // (and thus doesn't have to be checked here).
        return lgraph.getParentNode() == nil && lgraph.getProperty(
                LayeredOptions.CROSSING_MINIMIZATION_GREEDY_SWITCH_HIERARCHICAL_TYPE) as? GreedySwitchType != .OFF
    }

    // Second, if not hierarchical, check the slightly more complex non-hierarchical case
    let greedySwitchType = lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_GREEDY_SWITCH_TYPE) as? GreedySwitchType ?? .TWO_SIDED
    let interactiveCrossMin =
        lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_SEMI_INTERACTIVE) as? Bool ?? false ||
        lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_STRATEGY) as? CrossingMinimizationStrategy == .INTERACTIVE
    let activationThreshold =
        lgraph.getProperty(LayeredOptions.CROSSING_MINIMIZATION_GREEDY_SWITCH_ACTIVATION_THRESHOLD) as? Int ?? 0
    let graphSize = lgraph.getLayerlessNodes().count

    return !interactiveCrossMin 
            && greedySwitchType != .OFF 
            && (activationThreshold == 0 || activationThreshold > graphSize)
}

