package override func calculatePortRanks(
    _ node: org_eclipse_elk_alg_layered_graph_LNode,
    _ rankSum: Float,
    _ type: org_eclipse_elk_alg_layered_options_PortType
) -> Float {
    switch type {
    case .INPUT:
        var inputCount = 0
        var northInputCount = 0
        for port in node.getPorts() {
            if !port.getIncomingEdges().isEmpty {
                inputCount += 1
                if port.getSide() == .NORTH {
                    northInputCount += 1
                }
            }
        }

        var northPos = rankSum + Float(northInputCount)
        var restPos = rankSum + Float(inputCount)
        for port in node.getPorts(.INPUT) {
            if port.getSide() == .NORTH {
                setPortRank(port.id, northPos)
                northPos -= 1
            } else {
                setPortRank(port.id, restPos)
                restPos -= 1
            }
        }
        return Float(inputCount)

    case .OUTPUT:
        var pos = 0
        for port in node.getPorts(.OUTPUT) {
            pos += 1
            let rank = rankSum + Float(pos)
            setPortRank(port.id, rank)
        }
        return Float(pos)

    case .UNDEFINED:
        return 0
    }
}

package func setFirstLayerOrder(_ order: inout [[org_eclipse_elk_alg_layered_graph_LNode]], _ forwardSweep: Bool) -> Bool {
    guard !order.isEmpty else {
        return false
    }

    let firstIndex = forwardSweep ? 0 : max(0, order.count - 1)
    var firstLayer = order[firstIndex]

    for node in firstLayer {
        node.setProperty(Self.WEIGHT_KEY, Double.random(in: 0.0..<1.0))
    }

    firstLayer = stableSortByWeight(firstLayer)

    var index = 0
    while index < firstLayer.count {
        let node = firstLayer[index]
        order[firstIndex][index] = node
        node.setProperty(Self.WEIGHT_KEY, Double(index + 1))
        index += 1
    }

    return false
}

