package override func calculatePortRanks(
    _ node: org_eclipse_elk_alg_layered_graph_LNode,
    _ rankSum: Float,
    _ type: org_eclipse_elk_alg_layered_options_PortType
) -> Float {
    switch type {
    case .INPUT:
        var inputCount = 0
        var northInputCount = 0
        for port in node.getPorts() {
            if !port.getIncomingEdges().isEmpty {
                inputCount += 1
                if port.getSide() == .NORTH {
                    northInputCount += 1
                }
            }
        }

        let incr = 1.0 as Float / Float(inputCount + 1)
        var northPos = rankSum + Float(northInputCount) * incr
        var restPos = rankSum + 1 - incr
        for port in node.getPorts(.INPUT) {
            if port.getSide() == .NORTH {
                setPortRank(port.id, northPos)
                northPos -= incr
            } else {
                setPortRank(port.id, restPos)
                restPos -= incr
            }
        }

    case .OUTPUT:
        var outputCount = 0
        for port in node.getPorts() {
            if !port.getOutgoingEdges().isEmpty {
                outputCount += 1
            }
        }

        let incr = 1.0 as Float / Float(outputCount + 1)
        var pos = rankSum + incr
        for port in node.getPorts(.OUTPUT) {
            setPortRank(port.id, pos)
            pos += incr
        }

    case .UNDEFINED:
        break
    }

    // Java: consumed rank is always 1 for node-relative strategy.
    return 1
}

package func sortLinearSegments(
    _ layeredGraph: org_eclipse_elk_alg_layered_graph_LGraph,
    _ monitor: any org_eclipse_elk_core_util_IElkProgressMonitor
) -> [LinearSegment] {
    var segmentList: [LinearSegment] = []

    // Initialize ids and in/out priorities on all nodes.
    for layer in layeredGraph {
        for node in layer {
            node.id = -1

            var inPrio = Int.min
            var outPrio = Int.min
            for port in node.getPorts() {
                for edge in port.getIncomingEdges() {
                    let prio = edge.getProperty(org_eclipse_elk_alg_layered_options_LayeredOptions.PRIORITY_STRAIGHTNESS) as? Int ?? 0
                    inPrio = max(inPrio, prio)
                }
                for edge in port.getOutgoingEdges() {
                    let prio = edge.getProperty(org_eclipse_elk_alg_layered_options_LayeredOptions.PRIORITY_STRAIGHTNESS) as? Int ?? 0
                    outPrio = max(outPrio, prio)
                }
            }
            node.setProperty(Self.INPUT_PRIO, inPrio)
            node.setProperty(Self.OUTPUT_PRIO, outPrio)
        }
    }

    var nextLinearSegmentID = 0
    for layer in layeredGraph {
        for node in layer {
            if node.id < 0 {
                let segment = LinearSegment()
                segment.id = nextLinearSegmentID
                nextLinearSegmentID += 1
                _ = fillSegment(node, segment)
                segmentList.append(segment)
            }
        }
    }

    var outgoingList: [[LinearSegment]] = Array(repeating: [], count: segmentList.count)
    var incomingCountList: [Int] = Array(repeating: 0, count: segmentList.count)

    createDependencyGraphEdges(monitor, layeredGraph, &segmentList, &outgoingList, &incomingCountList)

    // Stable Kahn topological ordering.
    var queue: [LinearSegment] = []
    queue.reserveCapacity(segmentList.count)
    for segment in segmentList where segment.id >= 0 && segment.id < incomingCountList.count {
        if incomingCountList[segment.id] == 0 {
            queue.append(segment)
        }
    }
    queue.sort()

    var sortedSegments: [LinearSegment] = []
    sortedSegments.reserveCapacity(segmentList.count)

    while !queue.isEmpty {
        let segment = queue.removeFirst()
        sortedSegments.append(segment)

        let out = segment.id >= 0 && segment.id < outgoingList.count ? outgoingList[segment.id] : []
        for target in out {
            guard target.id >= 0 && target.id < incomingCountList.count else {
                continue
            }
            incomingCountList[target.id] -= 1
            if incomingCountList[target.id] == 0 {
                queue.append(target)
            }
        }
        queue.sort()
    }

    // Keep leftovers in deterministic order if any remain.
    if sortedSegments.count < segmentList.count {
        let seen = Set(sortedSegments.map(\.id))
        let leftovers = segmentList.filter { !seen.contains($0.id) }.sorted()
        sortedSegments.append(contentsOf: leftovers)
    }

    // Apply new ranking as segment/node ids, matching Java post-topological rewrite.
    for (rank, segment) in sortedSegments.enumerated() {
        segment.id = rank
        for node in segment.nodes {
            node.id = rank
        }
    }

    return sortedSegments
}

package func transformLayer(_ layer: org_eclipse_elk_alg_layered_graph_Layer) {
    var lastRep: NodeRep?

    for lNode in layer.getNodes() {
        let nodeRep = Self.isFlexibleNode(lNode) ? transformFixedOrderNode(lNode) : transformFixedPosNode(lNode)
        if lNode.id >= 0, lNode.id < nodeReps.count {
            nodeReps[lNode.id] = nodeRep
        }

        if let lastRep {
            var spacing = lastRep.origin.getMargin().bottom
                + (spacings?.getVerticalSpacing(lastRep.origin, lNode) ?? 0)
                + lNode.getMargin().top
            if !lastRep.isFlexible {
                spacing += lastRep.origin.getSize().y
            }
            _ = createEdge(
                origin: nil,
                weight: 0,
                delta: Int(ceil(spacing)),
                source: lastRep.tail,
                target: nodeRep.head
            )
        }

        lastRep = nodeRep
    }
}

package func insertInLayerEdgeAuxiliaryEdges() {
    for layer in lGraph?.getLayers() ?? [] {
        for node in layer.getNodes() where node.getType() == .NORMAL {
            for inLayerEdge in node.getConnectedEdges() where inLayerEdge.isInLayerEdge() {
                let srcIsDummy = inLayerEdge.getSource()?.getNode()?.getType() != .NORMAL
                guard let thePort = srcIsDummy ? inLayerEdge.getTarget() : inLayerEdge.getSource(),
                      let dummyNode = inLayerEdge.getOther(thePort).getNode(),
                      dummyNode.id >= 0,
                      dummyNode.id < nodeReps.count,
                      let dummyRep = nodeReps[dummyNode.id]?.head,
                      let portRep = portMap[ObjectIdentifier(thePort)],
                      let owner = thePort.getNode()
                else {
                    continue
                }

                let src: org_eclipse_elk_alg_common_networksimplex_NNode
                let tgt: org_eclipse_elk_alg_common_networksimplex_NNode
                if owner.getIndex() < dummyNode.getIndex() {
                    src = portRep
                    tgt = dummyRep
                } else {
                    src = dummyRep
                    tgt = portRep
                }

                _ = createEdge(origin: nil, weight: Self.EDGE_WEIGHT_BASE, delta: 0, source: src, target: tgt)
            }
        }
    }
}

private func processInLayerEdge(_ edge: LEdge, _ layerXPos: Double, _ edgeSpacing: Double) {
    guard let sourcePort = edge.getSource(),
          let targetPort = edge.getTarget() else { return }

    let sourceAnchorY = sourcePort.getAbsoluteAnchor().y
    let midY = (sourceAnchorY + targetPort.getAbsoluteAnchor().y) / 2.0

    if sourcePort.getSide() == .EAST {
        let bx = layerXPos + (sourcePort.getNode()?.getLayer()?.getSize().x ?? 0) + edgeSpacing
        let bendPoint = KVector(bx, midY)
        edge.getBendPoints().insert(bendPoint, at: 0)
    } else {
        let bendPoint = KVector(layerXPos - edgeSpacing, midY)
        edge.getBendPoints().insert(bendPoint, at: 0)
    }
}

private func calculateWestInLayerEdgeYDiff(_ layer: Layer) -> Double {
    var maxYDiff: Double = 0.0

    for node in layer.getNodes() {
        for outgoingEdge in node.getOutgoingEdges() {
            guard let sp = outgoingEdge.getSource(),
                  let tp = outgoingEdge.getTarget() else { continue }

            if layer === tp.getNode()?.getLayer()
                && sp.getSide() == .WEST {

                let sourcePos = sp.getAbsoluteAnchor().y
                let targetPos = tp.getAbsoluteAnchor().y
                maxYDiff = Swift.max(maxYDiff, Swift.abs(targetPos - sourcePos))
            }
        }
    }

    return maxYDiff
}

