}

private static func buildEdgeIndices(_ graph: Graph) -> [[Int]] {
    let nodeIndexLookup = Dictionary(uniqueKeysWithValues: graph.nodes.enumerated().map { ($0.1.id, $0.0) })
    var edgeIndices = Array(repeating: [Int](), count: graph.nodes.count)

    for edge in graph.edges {
        guard let a = nodeIndexLookup[edge.source],
            let b = nodeIndexLookup[edge.target] else {
                continue
        }
        edgeIndices[a].append(b)
        edgeIndices[b].append(a)
    }

    return edgeIndices
}

private func shortestDistances(
    from startID: String,
    adjacency: [String: [(nodeID: String, edgeID: String)]]
) -> [String: Int] {
    var queue = [startID]
    var distances: [String: Int] = [startID: 0]
    var index = 0

    while index < queue.count {
        let current = queue[index]
        index += 1

        for next in adjacency[current] ?? [] where distances[next.nodeID] == nil {
            distances[next.nodeID] = (distances[current] ?? 0) + 1
            queue.append(next.nodeID)
        }
    }

    return distances
}

private func shortestPathTree(
    from startID: String,
    adjacency: [String: [(nodeID: String, edgeID: String)]]
) -> (distances: [String: Int], parents: [String: (nodeID: String, edgeID: String)]) {
    var queue = [startID]
    var distances: [String: Int] = [startID: 0]
    var parents: [String: (nodeID: String, edgeID: String)] = [:]
    var index = 0

    while index < queue.count {
        let current = queue[index]
        index += 1

        for next in adjacency[current] ?? [] where distances[next.nodeID] == nil {
            distances[next.nodeID] = (distances[current] ?? 0) + 1
            parents[next.nodeID] = (current, next.edgeID)
            queue.append(next.nodeID)
        }
    }

    return (distances, parents)
}

private func bfs(
    from startID: String,
    adjacency: [String: [String]],
    maxDepth: Int?,
    allows: (String) -> Bool
) -> [String: Int] {
    let maxDepth = maxDepth ?? Int.max
    var seen: [String: Int] = [:]
    var queue: [(nodeID: String, distance: Int)] = [(startID, 0)]
    var index = 0

    while index < queue.count {
        let entry = queue[index]
        index += 1
        if entry.distance >= maxDepth { continue }

        for nextID in adjacency[entry.nodeID] ?? [] {
            guard allows(nextID), seen[nextID] == nil else { continue }
            let nextDistance = entry.distance + 1
            seen[nextID] = nextDistance
            queue.append((nextID, nextDistance))
        }
    }

    return seen
}

public func stronglyConnectedComponents() -> [[Package.Name]] {
    let groups = sequential.analyze(using: makeAdjacencyExtract()).scc()
    return groups.map { group in
        group.compactMap { nameByNode[$0] }.sorted()
    }
}
